// Investigation 5, Phase 2 (apply): writes the reviewed hint_en/hint_he/
// explanation_en replacements from the Phase 1 dry run
// (2026-07-29-regen-explanations-investigation5-dryrun.mjs) to the 183
// approved questions the Phase 0 LLM-judge pass classified as RESTATEMENT.
// The dry-run output was hand-reviewed against a sample of 18 rows spanning
// all 3 categories (bare restatement / Hebrew grammar / reading
// comprehension), cross-checked against live DB option text, before this
// script was written. See project_hint_he_gap.md's sibling investigation
// for the scoring writeup.
//
// Scope discipline, unchanged from the dry run: only hint_en, hint_he,
// explanation_en are written here. prompt_en/prompt_he/options/
// correct_answer/topic/difficulty are never touched by this script — the
// question a child sees and answers is unchanged, so this content doesn't
// need to go back through Pending Review.
//
// Tagging: each updated row gets 'explanation_regen_2026_07' appended to its
// existing tags array (never overwritten), so this batch stays
// distinguishable from the original generation batch and auditable later.
//
// The 7 rows where hint_en === explanation_en ("spoiler hints") are
// deliberately NOT in this list — see project_spoiler_hint_rows.md. Their
// explanations were judged fine; their defect is the hint, a separate task.
//
// Idempotent / safe to re-run: a row already carrying the
// 'explanation_regen_2026_07' tag is skipped, so re-running after a partial
// failure only touches the rows that didn't complete last time.
//
// Usage: set -a && source .env.local && set +a && node scripts/2026-07-29-apply-explanations-investigation5.mjs

import { createClient } from '@supabase/supabase-js'

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY)

const TAG = 'explanation_regen_2026_07'

// ─── the 183 reviewed replacements from the Phase 1 dry run ───
const UPDATES = [
  { id: 'cbb6b084-af5e-4a49-afef-4208f711a9b7', hint_en: "Look for the word 'is' — that word tells you where the equals sign goes, and the equation needs both an unknown and an equals sign.", hint_he: "חפש את המילה 'שווה' — היא מראה איפה שמים סימן שווה, והמשוואה צריכה גם נעלם וגם סימן שווה.", explanation_en: "Translate the sentence piece by piece: 'a number' = x, 'plus 4' = +4, 'is 10' = =10. Putting them in the same order as the sentence gives x+4=10. Option B is missing the '=10' so it's not an equation, and options C and D reverse the relationship (they put x on the side where 10 should be combined with 4, which doesn't match 'a number plus 4 is 10')." },
  { id: '2f02c99b-c66e-4e42-974a-3db8543f59ed', hint_en: "A quarter means splitting something into 4 equal parts and taking 1 of them — look for the fraction with 4 on the bottom and 1 on top.", hint_he: "רבע פירושו לחלק דבר ל-4 חלקים שווים ולקחת חלק אחד — חפשו שבר עם 4 במכנה ו-1 במונה.", explanation_en: "The word 'quarter' means 1 out of 4 equal parts, which is written as 1/4 (numerator 1, denominator 4). Option A (1/2) is one half, B (1/3) is one third, and D (2/4) is two quarters, which equals a half, not a quarter. Only C, 1/4, matches 'one quarter'." },
  { id: '5967eb34-eb03-4c36-83f6-8f8c23e32256', hint_en: "Think of the fraction as parts eaten over total equal parts.", hint_he: "חשבו על השבר כחלקים שנאכלו חלקי סך כל החלקים השווים.", explanation_en: "The chocolate bar is divided into 2 equal parts (that's the denominator), and Amir eats 1 of those parts (that's the numerator). Writing parts-eaten over total-parts gives 1/2." },
  { id: '7757eb15-a9d9-492f-910d-51e04fd1d556', hint_en: "Look at the bottom number — it tells how many equal parts the whole is split into, and the top number tells how many of those parts you have.", hint_he: "המספר התחתון אומר לכמה חלקים שווים מחלקים את השלם, והמספר העליון אומר כמה חלקים לוקחים.", explanation_en: "In a fraction, the denominator (bottom number) shows how many equal parts make up the whole, and the numerator (top number) shows how many parts are taken. For one half, the whole is split into 2 equal parts and 1 of them is taken, which is written as 1/2. The other options don't match this: 1/3 means 1 part out of 3, 1/4 means 1 part out of 4, and 2/4 means 2 parts out of 4 (which also equals 1/2 in value, but isn't written the way 'one half' is normally expressed)." },
  { id: '90494d65-bd36-4dba-965d-20baa1ceffac', hint_en: "Think of a fraction as parts eaten over total equal parts — how many slices total, and how many did Dana eat?", hint_he: "חשבו על שבר כחלקים שנאכלו מתוך כלל החלקים השווים - כמה פרוסות בסך הכל, וכמה דנה אכלה?", explanation_en: "The pizza is cut into 4 equal slices, so the whole is divided into 4 parts (the denominator is 4). Dana eats 1 of those slices (the numerator is 1). So the fraction she ate is 1/4." },
  { id: 'a4a00eaa-96fc-4839-9692-c1c61a0a7859', hint_en: "Count how many parts are shaded, then count the total number of equal parts — write shaded on top, total on bottom.", hint_he: "ספרו כמה חלקים צבועים וכמה חלקים יש בסך הכל — החלק הצבוע למעלה, הכל למטה.", explanation_en: "The whole is split into 4 equal parts (that's the bottom number, the denominator), and 2 of those parts are shaded (that's the top number, the numerator). Writing shaded parts over total parts gives 2/4." },
  { id: 'f04185ce-510c-4da6-b6c4-9383289b4681', hint_en: "Look at the words: 'one third' means the whole is split into 3 equal parts, and you take 1 of them. Match the numerator and denominator to that.", hint_he: "שימו לב למילה 'שליש' - זה אומר שהשלם מחולק ל-3 חלקים שווים, ולוקחים חלק אחד מהם. חפשו את השבר שמתאים לזה.", explanation_en: "A fraction is written as (parts taken)/(total equal parts). 'One third' means the whole is divided into 3 equal parts (denominator = 3) and 1 of those parts is taken (numerator = 1), giving 1/3. Option A (1/2) means one of two parts (a half), C (1/4) means one of four parts (a quarter), and D (3/3) means all three parts (a whole) - none of these match 'one third' except B." },
  { id: '90596474-4069-4822-b504-c9ed85965e15', hint_en: "Divide the numerator by the denominator: 1 ÷ 2, and think about place value (tenths).", hint_he: "חלקו את המונה במכנה: 1 ÷ 2, וחשבו על ספרת העשיריות.", explanation_en: "To convert a fraction to a decimal, divide the numerator by the denominator: 1 ÷ 2 = 0.5. So 1/2 = 0.5, matching option B. (0.25 equals 1/4, 0.2 equals 1/5, and 0.12 equals 12/100, so none of those match 1/2.)" },
  { id: 'c74d748b-3830-4b48-a6ba-5539c1931fea', hint_en: "Try converting the fraction so the denominator is 100 — think about what you'd multiply 4 by to get 100, then do the same to the top number.", hint_he: "נסו להפוך את המכנה ל-100 — במה צריך לכפול את 4 כדי לקבל 100? עשו את אותו הדבר למונה.", explanation_en: "To write 1/4 as a decimal, convert it to a fraction with denominator 100: multiply both top and bottom by 25, since 4 × 25 = 100. That gives 1/4 = 25/100. A fraction over 100 is written as two decimal places, so 25/100 = 0.25." },
  { id: '1d922ad7-75d6-440d-8472-2979c044605f', hint_en: "To divide fractions, multiply by the reciprocal of the second fraction — flip 5/3 first.", hint_he: "כדי לחלק שברים, הופכים את השבר השני וכופלים במקומו – הפוך את 5/3.", explanation_en: "Dividing by a fraction means multiplying by its reciprocal: 5/6 ÷ 5/3 = 5/6 × 3/5. Multiply numerators and denominators: (5×3)/(6×5) = 15/30. Simplify by dividing top and bottom by 15: 15/30 = 1/2." },
  { id: '9ba21ab9-8584-422f-be4b-c518df9e5e83', hint_en: "To multiply fractions, multiply the numerators together and multiply the denominators together separately.", hint_he: "כדי לכפול שברים, כופלים את המונים זה בזה ואת המכנים זה בזה בנפרד.", explanation_en: "To multiply fractions, multiply the numerators together and the denominators together: 1×3 = 3 (numerator) and 2×4 = 8 (denominator), giving 3/8. This fraction is already in simplest form since 3 and 8 share no common factors, so 3/8 is the final answer." },
  { id: '05adeaae-26e1-45a3-9e6b-252c3741b14a', hint_en: "For 'הוא' (he) in future tense, verbs take the prefix י-. Attach it to the root ק-ר-א the same way you would with other הוא verbs.", hint_he: "לגוף 'הוא' בעתיד מוסיפים את התחילית י- לשורש. חשבו איך זה עובד עם פעלים אחרים בגוף הוא.", explanation_en: "In future tense, each grammatical person has its own prefix: א- for אני, ת- for את/אתה, and י- for הוא/הם. Since the subject here is הוא, the root ק-ר-א takes the prefix י-, giving יקרא. תקרא would fit את/אתה, and אקרא would fit אני — but the subject is הוא, so יקרא is correct." },
  { id: '07fbc62b-3f77-499f-adc5-6d96ac3007f3', hint_en: "For אתם in future tense, use the prefix ת and add the plural ending ו at the end of the verb.", hint_he: "לגוף אתם בעתיד מוסיפים ת בהתחלה וסיומת ו בסוף הפועל.", explanation_en: "In future tense, אתם takes the prefix ת plus the plural suffix ו: ת + למד + ו = תלמדו. This matches the pattern used for other אתם verbs, like תכתבו or תשחקו. The other options belong to different subjects: נלמד is אנחנו, ילמדו is הם, and למדתם is past tense." },
  { id: '1415358a-9c09-4045-93bb-48210c4a6291', hint_en: "The subject is אנחנו (we), and the sentence is about this week (future tense) — think about which prefix goes with the 'we' form of להיות in future tense.", hint_he: "הפועל 'להיות' בעתיד לגוף 'אנחנו' מקבל אות מסוימת בתחילת המילה — איזו?", explanation_en: "The subject is אנחנו, so the verb להיות in future tense must match the 'we' form. Future tense verbs for אנחנו take the prefix נ-, giving נהיה (ננ+היה). היינו is past tense, יהיו is future for הם, and תהיה is future for את/אתה/הוא — none match אנחנו, so נהיה is correct." },
  { id: '30497b4b-d505-47d8-aace-ef45e4c26105', hint_en: "The sentence talks about tomorrow, so you need future tense. Match the prefix to the subject הוא (he) — think about which letter starts future-tense verbs for 'he'.", hint_he: "המשפט מדבר על מחר, אז צריך עתיד. חשבו איזו אות פותחת פועל בעתיד כשמדברים על 'הוא'.", explanation_en: "The word מחר (tomorrow) signals future tense, so the verb לכתוב must be conjugated in the future. In Hebrew future tense, the prefix marks the subject: א for אני, ת for את/היא, נ for אנחנו, and י for הוא/הם. Since the subject here is הוא, the correct prefix is י, giving יכתוב. כתב is past tense, תכתוב would fit את or היא, and אכתוב would fit אני — none match הוא." },
  { id: '31cf3981-78ee-4698-b7d1-1b8e58bf105a', hint_en: "The subject is 'אנחנו' (we). In future tense, first-person plural verbs take the prefix נ- before the root letters.", hint_he: "הנושא הוא 'אנחנו'. בזמן עתיד, גוף ראשון רבים מקבל את התחילית נ- לפני שורש הפועל.", explanation_en: "אנחנו משחקים is present tense, first-person plural. To form the future of the root ש-ח-ק for 'we', add the prefix נ- to the root: נ+שחק = נשחק. The other options belong to different subjects: ישחקו fits הם/הן (prefix י-...ו), תשחקו fits אתם/אתן (prefix ת-...ו), and שיחקנו is past tense, not future." },
  { id: '3451ef27-8eda-4683-b825-b8fae8db3319', hint_en: "The subject is הן (feminine plural), and future tense feminine plural verbs take the pattern תִ___נָה — check which option matches that ending.", hint_he: "הנושא הוא \"הן\" (נקבה רבות), ופועל בעתיד בגוף הזה מקבל תבנית תִ___נָה — בדקו איזו אפשרות מתאימה.", explanation_en: "The subject הן is feminine plural, and in future tense the feminine plural form always uses the pattern תִ___נָה (e.g., תלכנה, תשבנה). For the root ב-ו-א (לבוא), this gives תבואנה. The other options belong to different subjects: יבואו is masculine plural (הם), נבוא is first person plural (אנחנו), and תבוא is masculine/feminine singular (אתה/את/הוא/היא) — none matches הן." },
  { id: '3983b1d4-aac1-4dd7-8e63-afaff5d0d87f', hint_en: "In future tense, the pronoun determines the prefix: יכתוב is for הוא, אכתוב is for אני, נכתוב is for אנחנו — think about which prefix matches אתה.", hint_he: "בעתיד, אות היחס בתחילת הפועל תלויה בגוף: י- להוא, א- לאני, נ- לאנחנו — חשבו איזו אות מתאימה לאתה.", explanation_en: "In future tense, the prefix letter marks the grammatical person: א- for אני, י- for הוא, נ- for אנחנו, and ת- for אתה/את/היא. Since the subject here is אתה, the verb כתב takes the ת- prefix, giving תכתוב. The other options belong to different subjects: יכתוב (הוא), אכתוב (אני), נכתוב (אנחנו)." },
  { id: '664d908f-2f91-4c71-8058-b5b9ac534e8a', hint_en: "For את (feminine 'you') in future tense, use the prefix ת- plus a י- ending — think of the pattern תִ___י.", hint_he: "בגוף שני נקבה (את) בעתיד מוסיפים ת- בהתחלה ו-י- בסוף הפועל.", explanation_en: "The subject is את (feminine, second person). Future-tense verbs for את take the prefix ת- and the suffix י-, giving the pattern ת-ק-ר-א-י = תקראי. The other options belong to different subjects: יקרא is הוא, אקרא is אני, and נקרא is אנחנו." },
  { id: '859f88fe-d32f-40e9-9a46-019458821ea8', hint_en: "The subject is אנחנו (we), and the sentence talks about tomorrow — so the verb needs the future-tense prefix that matches 'we', not the past-tense ending.", hint_he: "הנושא הוא 'אנחנו', והמשפט מדבר על מחר - אז הפועל צריך את התחילית של עתיד המתאימה ל'אנחנו', לא את הסיומת של עבר.", explanation_en: "The subject is אנחנו (we), and future-tense verbs for 'we' take the prefix נ- (like ניגש, נלמד). From the root נ.ס.ע, the future 'we' form is נ+סע = נסע. Option א (נסענו) is past tense, ג (תסעו) matches אתם, and ד (יסעו) matches הם — none match אנחנו." },
  { id: '9d9abaa0-11c5-4f0d-b1e8-c8cb0c0d3ce7', hint_en: "For third-person masculine (הוא) in future tense, the verb takes the prefix י (not ת or א) — think of how ילד or הוא forms usually start.", hint_he: "לגוף שלישי זכר יחיד (הוא) בעתיד מוסיפים את התחילית י ולא ת או א.", explanation_en: "In future tense, the prefix on the verb tells you the subject: א = אני, ת = את/אתה/היא, י = הוא/הם, נ = אנחנו. Since the subject here is הוא, the root כ-ת-ב takes the prefix י, giving יכתוב. תכתוב would fit את/אתה, and אכתוב would fit אני — so only יכתוב matches הוא." },
  { id: 'b10ca689-ff75-498c-862b-4a461ac09a1c', hint_en: "The subject is אתן (feminine plural), so the future-tense verb needs the ת___נה pattern, not the masculine plural ending.", hint_he: "הנושא הוא אתן (נקבה, רבים), אז הפועל בעתיד צריך לקבל את התבנית ת___נה ולא את הסיומת של זכר רבים.", explanation_en: "The pronoun אתן is second-person feminine plural, and in future tense this form takes the prefix ת- plus the suffix נה-, giving תלכנה. The other options belong to different subjects: ילכו fits הם/הן (third person plural), תלכו fits אתם (masculine plural), and נלך fits אנחנו (first person plural) — none match אתן, so only תלכנה is correct." },
  { id: 'b689ccf8-c89f-4910-84ef-b9cd12c7d32c', hint_en: "The subject is היא (she) — future-tense verbs for היא/הוא take the prefix ת, not א, י, or the plural ending ו.", hint_he: "הנושא הוא 'היא' — פעלים בעתיד עבור היא/הוא מתחילים באות ת, לא באות א, י, או בסיומת ו של רבים.", explanation_en: "In future tense, the prefix attached to the root שיר depends on the subject: א for אני (אשיר), י for הוא (ישיר), ת for היא/אתה (תשיר), and the ending ו for plural subjects (ישירו). Since the subject here is היא, the correct form takes the ת prefix: תשיר." },
  { id: 'ba75710c-530a-4721-8bcf-3e2eb06466b6', hint_en: "Future tense for 'אני' takes the prefix א before the verb root - think about who is doing the action and match the prefix to that person.", hint_he: "בעתיד, לגוף 'אני' מוסיפים את התחילית א לפני שורש הפועל - שימי לב למי מבצע את הפעולה.", explanation_en: "כותב is present tense. In future tense, the pronoun אני always takes the prefix א־ (not י־, ת־ or נ־, which belong to הוא/את/אנחנו). So כותב (root כ-ת-ב) becomes אכתוב. יכתוב is wrong because the י־ prefix is for הוא, and כתבתי is past tense." },
  { id: 'ce384235-6738-49e7-b1db-1b4f6a41645b', hint_en: "Think about the subject: this is 'they' feminine (הן). In future tense, feminine plural verbs use the pattern תִּ...נָה, not the masculine ירוצו pattern.", hint_he: "שימי לב לנושא: זה 'הן' בלשון נקבה. בעתיד, נקבה רבות מקבלת את התבנית תִּ...נָה, ולא את התבנית של זכר.", explanation_en: "The subject is הן (they, feminine plural). Future tense feminine plural verbs take the prefix ת- and suffix נה- (pattern תקטולנה), giving תרוצנה. ירוצו is the masculine plural form (הם ירוצו), נרוץ is first person plural (אנחנו נרוץ), and רצו is past tense, not future — so only תרוצנה matches both the tense and the feminine plural subject." },
  { id: 'f1d4234b-ef91-460a-aba1-30a247bcdf0e', hint_en: "For 'הם' (they) in future tense, verbs take the prefix 'י'. Think about which option starts with that letter.", hint_he: "לגוף 'הם' בזמן עתיד מוסיפים את האות 'י' בתחילת הפועל. חשבו איזו תשובה מתחילה באות הזו.", explanation_en: "The subject is 'הם' (they), and in future tense the third-person plural takes the prefix 'י' before the root: י+אכלו = יאכלו. The option 'אכלו' is past tense, 'תאכלו' takes the prefix ת and matches 'אתם' (you, plural), and 'נאכל' takes the prefix נ and matches 'אנחנו' (we). Only 'יאכלו' correctly matches 'הם' with the future-tense י prefix." },
  { id: '26feed7f-a31c-46eb-b064-85bd34f5e4c1', hint_en: "Look at the noun הבנות - it's plural and feminine, so the adjective must match that gender and number ending, not just add 'ות' or use the masculine plural.", hint_he: "שימי לב שהמילה 'הבנות' היא נקבה רבים - התואר צריך להתאים גם במין וגם במספר.", explanation_en: "Adjectives in Hebrew must agree with the noun in gender and number. הבנות is feminine plural, so the adjective needs the feminine plural ending ות-, giving יפות. Option א (יפה) is feminine singular, option ג (יפים) is masculine plural (matches הבנים, not הבנות), and option ד adds an unrelated word. Only יפות matches הבנות correctly." },
  { id: '5aa9fe4a-caae-448e-943c-f25beb8fc5f8', hint_en: "Look at the word 'מחר' (tomorrow) — this tells you the sentence needs future tense, and check that the verb form matches 'אנחנו' (we).", hint_he: "שימו לב למילה 'מחר' — היא מרמזת על זמן עתיד, ובידקו שהפועל מתאים לגוף 'אנחנו'.", explanation_en: "The word 'מחר' (tomorrow) signals future tense, so the verb ללכת must be conjugated in the future, not past or present. For the pronoun אנחנו (we), the future form is נלך (we will go) — matching the ני/נ prefix used for 'we' in future tense verbs (like נכתוב, נשחק). הלכנו is past tense, הולכים is present tense, and ילכו is future but for the 'הם' (they) form, not אנחנו — so only נלך fits both the tense and the subject." },
  { id: '8dcb1631-5761-4c32-98f9-e6fa7c96bc31', hint_en: "The subject is הן (feminine plural). Future-tense verbs for הן take the prefix ת- and end in ־נה, unlike masculine plural which uses י-...-ו.", hint_he: "הנושא הוא 'הן' (נקבה רבות). בעתיד לנקבה רבות משתמשים בתחילית ת- וסיומת ־נה, בשונה מזכר רבים שמקבל י-...-ו.", explanation_en: "The subject הן is feminine plural, and in Hebrew future tense, feminine plural subjects (את/הן) take the pattern ת + root + נה. Applying this to the root א-כ-ל gives תאכלנה. The other options don't match: יאכלו is future masculine plural (הם), אכלו is past tense, and אוכלות is present tense feminine plural." },
  { id: 'b0859953-c979-44ed-9a94-3d9dfd6e5f41', hint_en: "Think about when the action happened — is 'תשיר' future, 'שרו' plural, or is one option already in past tense for 'she'?", hint_he: "שימי לב מתי קורית הפעולה - האם 'תשיר' זה עתיד, 'שרו' זה רבים, או שאחת האפשרויות היא כבר עבר יחיד נקבה?", explanation_en: "The verb must match 'היא' (she, singular feminine) and be in past tense. 'תשיר' is future tense (she will sing), 'שרו' is past plural (they sang), and 'שיר' is a noun (a song), not a verb. Only 'שרה' is the past-tense form for a singular feminine subject, matching 'היא' — so 'היא שרה' means 'she sang.'" },
  { id: 'c8172a59-28ad-47b0-9598-a09317909231', hint_en: "Future tense for 'he' uses the prefix י at the start of the verb - think about how 'הוא כותב' becomes 'הוא יכתוב'.", hint_he: "בזמן עתיד לגוף 'הוא' מוסיפים את האות י בתחילת הפועל - כמו ב'הוא יכתוב'.", explanation_en: "The verb here is אכל (root א-כ-ל). In present tense, 'הוא אוכל' means 'he eats/is eating'. To form future tense for third person masculine singular (הוא), Hebrew adds the prefix י to the future stem: י + אכל = יאכל, meaning 'he will eat'. The other options are wrong tenses or persons: אכל is past tense, אוכל is present tense, and יאכלו is future tense but plural (they will eat), not singular." },
  { id: 'e61b7642-abbd-48a9-a7e9-bb031aed78cb', hint_en: "This describes something that will happen in the future (after 'if it rains'), and the subject is 'we' (אנחנו). Which prefix marks future tense for 'we' in Hebrew verbs?", hint_he: "המשפט מתאר מה יקרה בעתיד (אחרי 'אם ירד גשם'), והפועל מתייחס ל'אנחנו'. איזו אות תחילית מציינת עתיד בגוף ראשון רבים?", explanation_en: "The sentence describes a future condition ('if it rains, we will stay home'), so the verb must be in future tense, not past or present. The subject is 'אנחנו' (we), and in Hebrew future-tense conjugation the first-person plural takes the prefix נ- (like נלך, נכתוב). Applying this to the root of להישאר gives נישאר. The other options are wrong tenses/persons: נשארנו is past tense, נשאר could be misread as present/singular-future mismatch, and ישארו is third-person plural future (הם ישארו), not 'we'." },
  { id: 'f9e40114-c81e-4ed9-9f73-41647d001649', hint_en: "Think about when the action happened: is it happening now, will it happen later, or did it already happen? Match the verb form to 'they' in the past tense.", hint_he: "חשבו מתי קרתה הפעולה - עכשיו, בעתיד, או בעבר? התאימו את הפועל לגוף 'הם' בזמן עבר.", explanation_en: "The verb אוכלים is present tense ('are eating'). To form the past tense for the subject הם ('they'), the verb changes to אכלו ('ate') - the root א-כ-ל takes the past-tense plural ending -ו. Note: יאכלו is future tense ('will eat'), and אכל is past tense but only for a single male subject (הוא אכל), not plural." },
  { id: 'fea80707-01ac-4a6a-b2a4-9db56057b394', hint_en: "The subject is 'אנחנו' and the sentence describes something happening this week (future), so look for the future-tense form that matches 'we', not past or singular forms.", hint_he: "הנושא הוא 'אנחנו' והמשפט מתאר משהו שיקרה השבוע (עתיד) — חפשו את צורת העתיד המתאימה ל'אנחנו', לא עבר או יחיד.", explanation_en: "The verb להיות conjugates in future tense as: אני אהיה, אתה תהיה, הוא יהיה, אנחנו נהיה, אתם תהיו, הם יהיו. Since the subject given is 'אנחנו' (we) and the sentence 'השבוע ___ מבחן' refers to a test happening this coming week (future), the correct form is נהיה. The other options don't fit: היינו is past tense (we were), יהיו is future for 'they', and תהיה is future for 'you' (singular) or 'she'." },
  { id: '16221fb8-77e2-4742-b30b-c7d250abec1a', hint_en: "Think of these as thousands: 3 thousand plus 2 thousand. Add just those digits, then attach the three zeros.", hint_he: "חשבו על זה כאלפים: 3 אלפים ועוד 2 אלפים. חברו את הספרות ואז הוסיפו את שלושת האפסים.", explanation_en: "3,000 is 3 thousands and 2,000 is 2 thousands. Adding the thousands: 3 + 2 = 5 thousands, which is written as 5,000. So 3,000 + 2,000 = 5,000." },
  { id: 'ce7194f2-7739-4ac8-b62d-b558ed3a016d', hint_en: "Think of these as thousands: subtract the number of thousands, then attach '000' to the result.", hint_he: "חשבו על זה כאלפים: חסרו את מספר האלפים, ואז הוסיפו '000' לתוצאה.", explanation_en: "Treat both numbers as thousands: 8,000 = 8 thousands and 3,000 = 3 thousands. Subtract the thousands: 8 - 3 = 5, so the answer is 5 thousands, or 5,000." },
  { id: '06b5b562-af9a-42a0-9b8b-e952b017304e', hint_en: "A square has 4 equal sides — think about how to combine the side length across all of them.", hint_he: "לריבוע יש 4 צלעות שוות — חשבו איך לשלב את אורך הצלע על פני כל הצלעות.", explanation_en: "A square has 4 equal sides, so perimeter = side × 4 = 6 × 4 = 24 cm." },
  { id: '14cb4d5e-0cab-491e-8f1c-96ef35c8c858', hint_en: "The perimeter of a rectangle means adding all four sides — two lengths and two widths.", hint_he: "היקף המלבן הוא סכום כל ארבע הצלעות - שני אורכים ושני רוחבים.", explanation_en: "A rectangle has two lengths and two widths, so perimeter = 7 + 2 + 7 + 2 = 18 cm." },
  { id: '3659c632-51f9-46f3-b1fe-4ee01895e2bc', hint_en: "Area = length × width, so think about what operation undoes multiplication by 3.", hint_he: "שטח = אורך × רוחב, חשבו איזו פעולה 'מבטלת' כפל ב-3.", explanation_en: "Area = length × width, so length = area ÷ width = 18 ÷ 3 = 6 cm." },
  { id: '9f49e8a0-a8d1-48d4-bb50-f12dde6f2ff4', hint_en: "The area of a square equals side times side — think about what to multiply, not add.", hint_he: "שטח ריבוע שווה צלע כפול צלע — חשבו על כפל, לא על חיבור.", explanation_en: "For a square, area = side × side. Here the side is 5 cm, so area = 5 × 5 = 25 cm² (not 5 + 5 = 10, which would be wrong)." },
  { id: '1b8f6a19-aa35-4106-bb1c-dbf96e225931', hint_en: "Think of a Hif'il verb like הִלְבִּישׁ (to dress someone) — compare it to its Pa'al root לבש (to wear) and notice who is causing whom to act.", hint_he: "חשבו על פועל בבניין הפעיל כמו הִלְבִּישׁ, והשוו אותו לשורש בבניין פעל (לבש) — שימו לב מי גורם למי לפעול.", explanation_en: "הפעיל is the causative binyan: it adds a causer to the action. Compare לבש (he wore, Pa'al — the subject himself wears) with הִלְבִּישׁ (he dressed someone, Hif'il — the subject causes another person to wear something). Similarly, ידע (he knew, Pa'al) becomes הודיע (he informed, Hif'il — caused someone else to know). This 'X caused Y to do/become Z' pattern is the hallmark of הפעיל, which is why it's the answer, not פעל (simple action), נפעל (passive/reflexive), or פיעל (intensive, not causative)." },
  { id: '26399e23-744f-4473-94c3-18330c73ce19', hint_en: "Think about which binyan's pattern adds an extra 'agent' who makes someone else do the action — compare לבש (he wore) with a form meaning 'he made someone wear.'", hint_he: "חשבו על הבניין שמוסיף 'גורם' שגורם למישהו אחר לבצע את הפעולה — השוו בין לָבַש (הוא לבש) לצורה שמשמעותה 'הוא גרם למישהו ללבוש'.", explanation_en: "Hifil (הפעיל) adds the prefix ה- and a causative meaning to the root: from ל.ב.ש (wear) it forms הִלְבִּישׁ (made someone wear/dressed someone), and from י.צ.א (go out) it forms הוֹצִיא (took/brought out, i.e., made go out). In both cases the subject causes another person or thing to perform or undergo the action, which is exactly what 'causative' means. The other binyanim don't add this meaning: Pa'al (A) gives the plain action (לָבַש - he wore), Nif'al (B) gives passive/reflexive (נִלְבַּשׁ), and Pi'el (D) often gives intensive action (לִבֵּשׁ - he dressed intensively), none of which mean 'caused someone else to act.'" },
  { id: '464e7cb1-dd45-4659-b43f-e9e25f9c9904', hint_en: "The infinitive (שם הפועל) is formed with the prefix ל attached to the root, not the present-tense or future-tense form — check which option is built that way.", hint_he: "שם הפועל נבנה מהתחילית ל + השורש, ולא מצורת הווה (כותב) או עתיד (יכתוב) — בדוק איזו אפשרות בנויה כך.", explanation_en: "In Pa'al, the infinitive pattern is לִקְטוֹל (li-ktol), so the root כ-ת-ב becomes לכתוב by adding the prefix ל to the base כתוב. Compare the other options: כותב is the present tense (הווה, 'writing/writes'), כתיבה is the noun form ('writing'), and יכתוב is the future tense ('will write'). Only לכתוב matches the infinitive pattern, so B is correct." },
  { id: '4cc166c6-2c75-44bc-9360-c0e56c2141f0', hint_en: "Check the prefix and vowel pattern: Hif-il is active (Hi-...i-) while Huf-al is its passive counterpart (Hu-...a-). Which one fits הכניס?", hint_he: null, explanation_en: "הכניס breaks down as Hi-CH-N-I-S, matching the Hif'il pattern Hi-1-2-i-3 (like Hi-CH-N-I-S from root כ.נ.ס). Hif'il is active and causative — הכניס means 'caused to enter,' i.e., the subject actively makes someone/something enter. This rules out Huf'al, which is the passive counterpart (e.g., huchnas, 'was inserted'), and Niphal/Hitpa'el, whose prefixes (ni-, hit-) don't match the Hi- form seen here." },
  { id: '4f3ced7d-2061-4f64-a070-0c5614c3bcce', hint_en: "Try listing each Binyan one by one and see how many you reach before you run out of patterns.", hint_he: null, explanation_en: "The seven Binyanim are: Pa'al, Nif'al, Pi'el, Pu'al, Hif'il, Huf'al, and Hitpa'el — three active/simple patterns (Pa'al, Pi'el, Hif'il), their passive counterparts (Nif'al partly, Pu'al, Huf'al), and the reflexive Hitpa'el. Counting this fixed list gives 7, matching option B." },
  { id: 'bdee1014-68a7-4876-bc37-1d6004ac1b91', hint_en: "Pa'al infinitives usually follow the pattern לִ + [root letters with a between the 2nd and 3rd] — think of the root כ-ת-ב and add the prefix and vowel pattern to it, rather than looking at the present-tense form (A) or the noun form (C).", hint_he: "שם הפועל בבניין פעל נבנה לרוב בתבנית לִ+שורש עם 'o' בין העיצור הראשון לשני — קח את השורש כ-ת-ב והפעל עליו את התבנית, ולא את צורת ההווה (א) או צורת שם העצם (ג).", explanation_en: "The Pa'al infinitive pattern is לִ + פ + ְ + ע + וֹ + ל (li-CVoC), so for the root כ-ת-ב you get לכתוב. Option A (כותב) is the present-tense/participle form, meaning 'writing/writer'; option C (כתיבה) is the noun 'writing'; option D (יכתוב) is the future tense 'he will write'. Only לכתוב fits the infinitive pattern, so B is correct." },
  { id: 'd1bbe59e-995c-4c2a-b9bf-9bb232c54888', hint_en: "Pi-el's pattern is CiCeC — think of the vowel pattern i-e placed between the three root letters S-P-R.", hint_he: null, explanation_en: "Pi-el verbs follow the pattern CiCeC: the first root letter gets a 'i' sound, the second gets an 'e' sound. Applying this to S-P-R gives Si-P-eR, spelled סיפר (siper, 'told'). ספר lacks the doubling/vowel pattern of Pi-el, הספיר fits Hif'il (heCCiC), and נספר fits Nif'al (niCCaC)." },
  { id: 'e762ee5e-49d0-4143-bba0-711dd29b48db', hint_en: "Passive past tense in Hebrew usually comes from binyan Pu'al — think about how Pu'al past-tense verbs are vowelled, and match the ending to a feminine subject like 'ארוחת הערב'.", hint_he: null, explanation_en: "The sentence needs a passive, past-tense, feminine verb from ב-ש-ל. Passive past is formed with binyan Pu'al, whose past-tense pattern is CuCaC (u-a vowels), and the feminine ending is -ה. Applying this to ב-ש-ל gives בושל + ה = בושלה, matching 'ארוחת הערב' (feminine subject). The other options fail: בישל is active Pi'el (Mom cooked, not was cooked), התבשל is Hitpa'el (reflexive, 'cooked itself'), and מבושל is a Pu'al participle/adjective ('is cooked'), not the past-tense verb needed here." },
  { id: '19807414-a9b7-44bc-af17-75188433f2cd', hint_en: "Look at how the base form כותב changes: add ת for feminine singular, ים for masculine plural, and ות for feminine plural — check which row applies these endings in the right order.", hint_he: null, explanation_en: "In Pa'al present tense, the root כ-ת-ב follows the pattern: masc. sg. כותב (no ending), fem. sg. כותבת (add ת), masc. pl. כותבים (add ים), fem. pl. כותבות (add ות). Row A lists exactly these four forms in that order — כותב, כותבת, כותבים, כותבות — matching the required masc sg / fem sg / masc pl / fem pl sequence. The other rows either repeat the same word (B), scramble the forms out of order (C), or misassign endings to the wrong gender/number (D)." },
  { id: '21723fff-f683-4a62-b1a3-f47ae3080f24', hint_en: "Pa'al present tense uses the pattern שׁוֹמֵר (CoCeC) — insert the vowels around the three root letters ש-מ-ר, don't add prefixes like תִ/יִ or נ.", hint_he: "בהווה של בניין פעל המשקל הוא שׁוֹמֵר (קוֹטֵל) — יש להכניס את התנועות בין אותיות השורש ש-מ-ר, בלי תוספות כמו יִ/תִ או נ.", explanation_en: "The present tense (הווה) of Pa'al follows the משקל קוֹטֵל pattern: root letter1 + וֹ + root letter2 + ֵ + root letter3. For ש-מ-ר this gives שׁוֹמֵר (sho-mer) = 'guards/guarding.' The other options belong to different tenses: שָׁמַר (A) is past tense, יִשְׁמוֹר (B) is future tense, and נִשְׁמָר (D) is the Nif'al binyan, not Pa'al present." },
  { id: '30e031dc-2da3-4302-938d-bdd78a15128a', hint_en: "Look at the verb ending: does it show past action already completed, or is it happening now/will happen later? Match the tense to 'he wrote.'", hint_he: "שימו לב לצורת הפועל: האם הפעולה כבר הסתיימה, קורית עכשיו, או עתידה לקרות? התאימו לזמן של 'הוא כתב'.", explanation_en: "כתב is the correct form because 'he wrote' describes a completed past action, and in Pa'al the past tense for third person masculine singular (הוא) uses the root כ-ת-ב with no prefix and no suffix: כתב. Compare: כותב has the pattern of the present tense (הווה, meaning 'writes/is writing'), יכתוב carries the future-tense prefix י- (meaning 'will write'), and נכתב belongs to the Nif'al pattern with the prefix נ- (meaning 'was written', passive). Since only כתב matches both the Pa'al pattern and the past-tense meaning of 'he wrote,' it is the correct answer." },
  { id: '3dce39b1-b0b0-4075-873d-6cd56479d393', hint_en: "Look at the subject הבנות — check both its gender and number, then match the verb's ending to it.", hint_he: null, explanation_en: "The subject הבנות is feminine plural, so the present-tense verb כותב (root כ-ת-ב, binyan Pa'al) must take the feminine plural ending ־ות, giving כותבות. Compare: כותב (masc. sing.), כותבת (fem. sing.), כותבים (masc. pl.) — only כותבות matches both the gender and number of הבנות." },
  { id: '760ef77d-4a5a-4ce9-aa9d-8bff88f7d40b', hint_en: "Start from the masculine singular form of ללמוד, then add the ending used for masculine plural verbs.", hint_he: null, explanation_en: "The root ל.מ.ד in binyan Pa'al gives the present-tense masculine singular form לומד. To form masculine plural, add the suffix ים: לומד + ים = לומדים. (לומדת has the feminine singular ending ת, and לומדות has the feminine plural ending ות, so both are ruled out.)" },
  { id: '97001cd9-702d-4e49-8111-57547872323a', hint_en: "The verb ללמוד (present tense, binyan Pa'al) only takes the endings ־, ־ת, ־ים, ־ות — check which option adds an ending that doesn't exist in this set.", hint_he: null, explanation_en: "In binyan Pa'al, the present tense of ללמוד takes only four forms: לומד (masc. singular), לומדת (fem. singular), לומדים (masc. plural), לומדות (fem. plural). The ending ־ון is not one of the standard present-tense suffixes, so לומדון is not a real word — making D the incorrect form." },
  { id: '9fa8ecaa-e6a6-4d14-9a6f-a1ff337fef7e', hint_en: "Match each form to its subject: masculine singular, feminine singular, masculine plural, feminine plural — in that order — and check the standard present-tense endings (no ending, ־ת, ־ים, ־ות).", hint_he: null, explanation_en: "The present tense (הווה) of לאכול follows the standard Pa'al pattern for the root א-כ-ל: masculine singular אוֹכֵל (no suffix), feminine singular אוֹכֶלֶת (suffix ־ת), masculine plural אוֹכְלִים (suffix ־ים), feminine plural אוֹכְלוֹת (suffix ־ות). Option A lists exactly this order — אוכל, אוכלת, אוכלים, אוכלות — matching each form to its correct gender/number ending, so it is correct. The other options either repeat the same form four times (B) or scramble the forms into the wrong order (C, D), breaking the match between ending and subject." },
  { id: 'a2288884-5d34-422c-8f65-1977dd5b75e3', hint_en: "For 'they' in future tense, Pa'al verbs take the prefix י and end with ו — think of the pattern י__ְ__וּ applied to the three root letters ל-מ-ד.", hint_he: "בעתיד עבור 'הם' בבניין פעל מוסיפים את התחילית י ואת הסיומת ו לפי התבנית י__ְ__וּ על שורשי ל-מ-ד.", explanation_en: "In Pa'al future tense, third-person masculine plural ('they') uses the pattern י + [root] + ו: יִ-פְ-עֲ-לוּ. Applying this to the root ל-מ-ד gives י-ל-מ-ד-ו = ילמדו ('they will learn'). Option A (למדו) is past tense, not future. Option B (לומדים) is present tense. Option D (ילמד) is future but singular ('he will learn'), missing the ו plural ending." },
  { id: 'a9eb2dec-82be-492f-938c-f45fdc887a05', hint_en: "Think about the pattern for present-tense verbs: masculine plural usually ends in ים, and feminine plural has a different matching ending — apply that to אוכל.", hint_he: null, explanation_en: "The root א-כ-ל in Pa'al present tense conjugates as: אוכל (m. sg.), אוכלת (f. sg.), אוכלים (m. pl.), אוכלות (f. pl.). Since the question asks for feminine plural, the ת of אוכלת is dropped and replaced with the plural ending ות, giving אוכלות — option D." },
  { id: 'b7fb8314-8443-4218-9426-f24c8fc01b2f', hint_en: "Check both the gender and the number of the subject, then find the verb form (with -ים or -ות ending) that matches both.", hint_he: null, explanation_en: "The subject הילדים is masculine plural, so the verb must take the masculine plural present-tense ending -ים: לומד + ים = לומדים. Option A pairs a singular subject (הילד) with a plural verb (לומדות); B and D pair plural subjects with singular verbs (לומד). Only C, הילדים לומדים, matches both gender (masculine) and number (plural) between subject and verb." },
  { id: 'c90addc8-641f-4e57-8a51-1f362fba2eca', hint_en: "Think about the pattern for present tense (בינוני) verbs: masculine singular has no ending, but feminine singular adds a suffix. Check which option has that ending without also marking plural.", hint_he: null, explanation_en: "The root כ-ת-ב in the Pa'al present tense (הווה) follows the pattern כותב (masc. sing.) / כותבת (fem. sing.) / כותבים (masc. pl.) / כותבות (fem. pl.). Feminine singular is formed by adding the suffix ־ת to the masculine base כותב, giving כותבת — not ־ים or ־ות, which mark plural forms. So B is correct." },
  { id: 'cd171166-f16d-4dbb-8a0c-6f422d8e2447', hint_en: "Present tense (הווה) in binyan pa'al follows the pattern פ-ו-על for masculine singular — think of the vowel pattern, not the past or future form.", hint_he: null, explanation_en: "The root ש-מ-ע in binyan pa'al present tense (הווה) takes the pattern פועל: ש+ו+מ+ע = שומע. This differs from שמע (past tense, no ו), ישמע (future, with י- prefix), and שמעתי (past tense, first person). Since the question asks for present tense with הוא, the correct form is שומע." },
  { id: 'd64e3cad-1ffe-4423-b63f-a45a70164cf6', hint_en: "Think about the pattern for Pa'al present tense: masculine singular has no extra ending, feminine adds ת, and plural forms add ים or ות. Match לכתוב to the masculine singular slot.", hint_he: null, explanation_en: "The Pa'al present tense pattern for the root כ-ת-ב follows: masculine singular = כותב (no suffix), feminine singular = כותבת (+ת), masculine plural = כותבים (+ים), feminine plural = כותבות (+ות). Since the question asks for masculine singular, the form with no added ending, כותב, is correct — not כותבת (feminine), כותבים (plural masc.), or כותבות (plural fem.)." },
  { id: 'f249af41-4b46-41b8-a412-49890e33bf51', hint_en: "Look at the endings: past tense 3rd person masculine singular in Pa'al has no extra suffix added to the root pattern, unlike 'I' (תִּי) or future (יִ...) forms.", hint_he: "שימו לב לסיומות: גוף שלישי יחיד זכר בעבר בבניין פעל לא מקבל סיומת נוספת, בשונה מ'אני' (תִּי) או מהעתיד (יִ...).", explanation_en: "Pa'al past tense follows the pattern קָטַל: root כ-ת-ב fits into this pattern as כָּתַב, meaning 'he wrote' (3rd person masculine singular, no suffix needed since 'he' is the default form). Compare: כָּתַבְתִּי (A) adds תִּי for 'I wrote'; כּוֹתֵב (C) is the present-tense pattern קוֹטֵל meaning 'writes/writing'; יִכְתֹּב (D) adds the future prefix יִ־ meaning 'he will write'. Since the question asks for past tense 'he wrote', only כָּתַב matches both the tense and person." },
  { id: 'fb604460-a0a4-4194-9d67-4af18f7f1f7c', hint_en: "For 'אני' in past tense Pa'al, the root ל-מ-ד takes the ending '-תי' attached to the base למד.", hint_he: null, explanation_en: "The root ל-מ-ד in past tense Pa'al conjugates by adding person suffixes to the base למד. For first person singular (אני), the suffix is תי-, giving למד + תי = למדתי. The other options are different tenses: ילמד is future (הוא ילמד), לומד is present participle (הוא/אני לומד), and למד alone is past tense but third person (הוא למד), not first person." },
  { id: '31aaf269-433b-49ad-8abb-2b2066698767', hint_en: "Most English nouns add -s for plural, but a few common ones change form completely — think about how you'd say 'one child, two ___'.", hint_he: "רוב שמות העצם באנגלית מקבלים -s ברבים, אבל כמה מילים נפוצות משנות צורה לגמרי — חשבו איך אומרים 'one child, two ___'.", explanation_en: "Normally English plurals are formed by adding -s or -es (dog → dogs, box → boxes). 'Child' does not follow this rule — it's an irregular noun that changes form to 'children', just like man → men or woman → women. So the correct plural is children, not childs or childes." },
  { id: '64808f1f-c7e2-440a-a820-d162de17b9a5', hint_en: "Check each sentence's word order: does it follow subject (noun) + verb + object, the normal pattern in English?", hint_he: "בדקי את סדר המילים בכל משפט: האם הוא הולך לפי נושא (שם עצם) + פועל + מושא, הסדר הרגיל באנגלית?", explanation_en: "A correctly formed English sentence follows Subject + Verb + Object order, and the noun/subject must be paired with a verb that agrees with it. In 'Tamar eats her lunch,' 'Tamar' (noun/subject) comes first, followed by the verb 'eats,' followed by the object 'her lunch' — this matches standard sentence structure. The other options break this order: 'The quickly cat runs' misplaces the adverb before the noun, 'She beautiful is' reverses the adjective and verb, and 'Runs the dog fast' puts the verb before the subject noun." },
  { id: '6bb653c3-bb53-424e-b5d8-3a1c7938998b', hint_en: "Look at the ending of each word — one option has an extra letter added to show 'more than one'.", hint_he: "שימו לב לסוף כל מילה — באחת האפשרויות יש אות נוספת שמראה 'יותר מאחד'.", explanation_en: "Dogs = dog + s. Adding -s to a singular noun like 'dog' makes it plural, meaning more than one. Book, Child, and Boy have no -s ending, so they are all singular (one item)." },
  { id: '8588e9b5-2b1d-4ebb-a7e5-ca81c9d86f9f', hint_en: "Look at the verb ending in each sentence — past tense verbs in Hebrew often end in 'תי' for 'I'.", hint_he: "שימו לב לסיומת הפועל במשפט — פועל בזמן עבר בגוף ראשון מסתיים לרוב ב-'תי'.", explanation_en: "The verb 'הלכתי' ends with the suffix 'תי', which marks first-person past tense in Hebrew (root ה-ל-כ, past tense conjugation). Compare: 'הולך' (option א and ד) is present tense, and 'אלך' (option ב) is future tense, marked by the prefix א. Only 'הלכתי' shows the past-tense 'תי' ending, so option ג is correct." },
  { id: 'c340f141-764f-4e8c-a84a-693651d5aab1', hint_en: "Look at who the word refers to in real life, and check the word's ending — most masculine nouns have no special feminine suffix like -ah (ה-).", hint_he: null, explanation_en: "The noun ילד (Yeled) refers to a male child, and it lacks the typical feminine ending ה- (as in ילדה, 'girl'). Since it denotes a male and has no feminine marker, ילד is grammatically masculine — matching option A." },
  { id: '9898bd45-3a8f-496e-9f92-7b1de8fdf61f', hint_en: "Find the main noun in the sentence first, then check which words before it are describing/modifying that noun — a noun phrase must include all of them plus the noun itself.", hint_he: "מצא קודם את שם העצם המרכזי במשפט, ואז בדוק אילו מילים לפניו מתארות אותו — צירוף השם חייב לכלול את כולן יחד עם שם העצם.", explanation_en: "The core noun here is \"dog.\" The words \"The,\" \"big,\" and \"brown\" all come before it and describe which dog is meant, so they belong with it in one unit: \"The big brown dog.\" The verb phrase \"ran quickly\" tells what the dog did, not what it is, so it's excluded. \"big brown\" alone is missing the noun it describes, and \"dog ran\" wrongly mixes the noun with part of the verb phrase — neither forms a complete noun phrase." },
  { id: 'f1d7a363-8af0-401d-8005-30a3d4fd8549', hint_en: "Check each option: does it name a person, place, or thing, or does it describe an action or quality instead?", hint_he: "בדקו כל מילה: האם היא מציינת אדם, מקום או דבר, או שמא היא מתארת פעולה או תכונה?", explanation_en: "To find the noun, test each option: 'Run' names an action (verb), 'Happy' describes a feeling (adjective), 'Quickly' describes how something is done (adverb), but 'School' names a place — something you can point to and put 'the' or 'a' in front of. Since it names a place, 'School' is the noun." },
  { id: '0e79cf21-f0e0-404c-b91c-9f4e20ec3547', hint_en: "The word אתמול means 'yesterday,' so the verb must be in the past-tense form (like the ק.ט.ל pattern כתב), not future (יכתוב) or present (כותב).", hint_he: "המילה אתמול מרמזת שהפועל חייב להיות בזמן עבר, לא עתיד (יכתוב) ולא הווה (כותב).", explanation_en: "אתמול ('yesterday') tells us the action already happened, so we need the past-tense form of the verb כ.ת.ב. In past tense, third-person masculine singular is כתב (he wrote), matching 'הילד כתב אתמול' (the boy wrote yesterday). יכתוב is future tense ('he will write'), כותב is present tense ('he writes/is writing'), and יכתב is also future — none of these can pair with אתמול, which requires a completed past action." },
  { id: '12e5463b-e67f-4ee4-b8fd-3a8040808eae', hint_en: "Look at the example words 'quickly' and 'loudly' — think about what part of the action they are telling you more about.", hint_he: "שימי לב למילים כמו 'מהר' ו'בקול רם' — חשבי על איזה חלק של הפעולה הן מוסיפות מידע.", explanation_en: "In 'she runs quickly,' the word 'runs' is the verb, and 'quickly' tells us HOW she runs — so it describes the verb, making it an adverb. That matches option B. It can't be A (naming a thing, like a noun), C (connecting sentences, like a conjunction), or D (replacing a noun, like a pronoun), since 'quickly' does none of those jobs." },
  { id: '150a3ea9-47c6-4576-a309-cb7c273b95cb', hint_en: "Check each option for both a subject (who?) and a verb (what action?) — a full sentence needs both.", hint_he: "בדקו בכל אפשרות אם יש גם נושא (מי?) וגם פועל (עשה מה?) - למשפט שלם צריך את שניהם.", explanation_en: "A complete sentence needs both a subject and a verb. הילד is only a subject with no action, רץ מהר and ילד גדול have no clear subject performing a stated action as a full sentence, but הילד רץ has the subject הילד (the boy) paired with the verb רץ (ran), so it expresses a complete thought." },
  { id: '21c473e1-742e-45e2-adc9-dd57de230423', hint_en: "The adjective must match the noun in gender and number — check whether ׳ספרים׳ is masculine/feminine and singular/plural, then pick the matching adjective ending.", hint_he: "שם התואר חייב להתאים לשם העצם במין ובמספר — בדקו אם ׳ספרים׳ הוא זכר או נקבה, יחיד או רבים, ובחרו את הסיומת המתאימה.", explanation_en: "ספרים is a masculine plural noun (ending in ־ים), so its adjective must also be masculine plural. חדש is masculine singular, חדשה is feminine singular, and חדשות is feminine plural — none match. Only חדשים carries the masculine plural ending ־ים that agrees with ספרים, giving הספרים חדשים." },
  { id: '2c125348-e2c5-4f10-8ee4-5e5d6f9abcb5', hint_en: "Ask which word tells you what kind of cat it is — look for the describing word right before the noun.", hint_he: "שאל איזו מילה מתארת איזה מין חתול זה — חפש את מילת התיאור שלפני שם העצם.", explanation_en: "An adjective describes a noun. In this sentence, 'cat' is the noun, and 'small' answers the question 'what kind of cat?' — so 'small' is the adjective. 'The' is an article, and 'sat' is the verb telling what the cat did." },
  { id: '2fec4f8d-5046-44b7-8eef-b78ae01a7a3c', hint_en: "Check the ending of ילדה — singular feminine nouns usually pair with adjectives ending in ה.", hint_he: "שימו לב לסיומת של המילה ילדה — שם עצם יחיד בנקבה מתאים לתואר שמסתיים ב-ה.", explanation_en: "ילדה is singular and feminine (it ends in ה, like most feminine nouns). Adjectives must match the noun in gender and number, so the feminine singular form of גדול is needed — that form is גדולה (adding/changing the ending to ה). גדול is masculine singular, גדולים is masculine plural, and גדולות is feminine plural, so none of those match ילדה." },
  { id: '44b96a31-487c-4483-a659-abc9b41576ef', hint_en: "Look for a word that describes the dog (adjective) and a word that describes how the dog barked (adverb) — you need both in the same sentence.", hint_he: "חפשו מילה שמתארת את הכלב (שם תואר) ומילה שמתארת איך הכלב נבח (תואר פועל) - שתיהן צריכות להיות באותו משפט.", explanation_en: "An adjective describes a noun, and an adverb describes a verb (often ending in -ly). In 'The big dog barked loudly,' 'big' describes the noun 'dog' (adjective), and 'loudly' describes the verb 'barked,' telling how the dog barked (adverb). The other options each have only one or neither: 'The dog barked' has no describing words, 'A dog and a cat' has only nouns, and 'She quickly ran' has only the adverb 'quickly' with no adjective." },
  { id: '50e37ad7-cf66-4913-89e2-b54a60a5e750', hint_en: "Look at the subject הספרים - is it singular or plural? Then check the sentence for time clues to decide past, present, or future tense.", hint_he: "בדקו את הנושא הספרים - יחיד או רבים? ואז חפשו רמז לזמן במשפט (עבר, הווה או עתיד).", explanation_en: "The subject הספרים is plural (masculine), so the verb 'to be' must agree in number: הוא is singular, ruling out א. The sentence describes a state without future markers, so it's past tense, not future - eliminating ד (יהיו, future plural) and ב (הם, which is a pronoun, not a form of 'to be'). Past tense plural of היה is היו, matching הספרים החדשים היו על השולחן = 'the new books were on the table.'" },
  { id: '535b397b-0856-4400-979a-5120b6e0696f', hint_en: "Think about when the action happened: is הוא כותב describing now, before, or later? Match the verb form to the time frame.", hint_he: "חשבו על הזמן שבו קרתה הפעולה: האם ״הוא כותב״ מתאר עכשיו, קודם, או אחר כך? התאימו את הפועל לזמן.", explanation_en: "כותב is present tense (הווה) — 'he writes/is writing'. To move to past tense (עבר), the root כ-ת-ב takes the past-tense pattern for third person masculine singular, which is כתב ('he wrote'), not the present form (כותב), future form (יכתוב, which adds the future prefix י-), or כתבן (not a real verb form of this root). So the past tense of הוא כותב is הוא כתב." },
  { id: '708f411a-db04-484f-86ce-69cd5eca04b9', hint_en: "Think about each option: does it name a person/thing, show action, connect words, or add detail about a noun? Match that to what adjectives do.", hint_he: "חשבו על כל אפשרות: האם היא מציינת שם, מתארת פעולה, מחברת מילים, או מוסיפה פרט על שם עצם? התאימו זאת לתפקיד של שם תואר.", explanation_en: "Option A (action word) describes verbs like 'run' or 'jump.' Option C (naming word) describes nouns themselves, like 'dog' or 'city.' Option D (connecting word) describes conjunctions like 'and' or 'but.' Only option B fits adjectives, since a word like 'big' in 'big dog' adds detail describing the noun 'dog' rather than naming it, showing action, or connecting words." },
  { id: 'a1723faf-4745-4ea0-80de-549dc87fa70c', hint_en: "Check the noun's gender and number, then find the verb form that matches both — feminine plural verbs in Hebrew often end in ־ות.", hint_he: "בדקו את המין והמספר של השם, ואז מצאו את הפועל שמתאים לשניהם — פעלים בנקבה רבים מסתיימים לרוב ב־ות.", explanation_en: "הילדות is feminine plural (the ־ות ending marks plural, and ילדה is feminine). The verb must agree in both gender and number, so it needs the feminine plural form, which also ends in ־ות: רצות. The other options fail to match: רצים is masculine plural, רץ is masculine singular, and רצה is feminine singular — none agree with הילדות on both counts." },
  { id: 'a294769e-c28f-4799-993b-7a4fee244636', hint_en: "Look at the prefix on the verb יכתוב — certain prefixes signal actions that haven't happened yet.", hint_he: "שימו לב לקידומת של הפועל יכתוב — היא מסמנת פעולה שעוד לא קרתה.", explanation_en: "The verb יכתוב is built with the prefix י־ attached to the root כ-ת-ב, which is the pattern used for future tense (הוא יכתוב = he will write). Compare: past would be כתב (he wrote) and present would be כותב (he writes/is writing). Since יכתוב matches the future pattern, 'הילד יכתוב' means 'the boy will write' — future tense (עתיד)." },
  { id: 'c7ddc525-de03-4591-bfd1-e921f8a0e1ca', hint_en: "Check the noun ילד: is it masculine or feminine, singular or plural — the adjective ending must match all of that.", hint_he: "בדקו את המילה ילד: זכר או נקבה, יחיד או רבים - סיומת שם התואר חייבת להתאים.", explanation_en: "ילד is masculine singular, so the adjective must also be masculine singular. גדול is the masculine singular form (no ה- ending like גדולה, no ים- like גדולים, no ות- like גדולות), so 'ילד גדול' is the correct match." },
  { id: 'cc97c37a-be7b-464b-97be-cd3b4492b116', hint_en: "Check the ending of the noun and the ending of the adjective — do they match in gender?", hint_he: "בדקו את הסיומת של שם העצם ואת הסיומת של שם התואר - האם הן מתאימות במין?", explanation_en: "ילד is a masculine singular noun (no ה ending), so it must be paired with the masculine adjective גדול. In option ג, it is paired with גדולה, which is the feminine form (with the ה ending, matching feminine nouns like ילדה). Because a masculine noun is joined with a feminine adjective, ילד גדולה shows disagreement — unlike ילד גדול (m.+m.), ילדה גדולה (f.+f.), or ילדים גדולים (m. pl.+m. pl.), which all match correctly." },
  { id: 'f009d71d-339f-4069-bbeb-8130f2bfb437', hint_en: "Check whether the subject 'המורות' (feminine plural) and the verb 'לימדו' agree in gender, number, and tense — does the verb form match a plural subject regardless of gender, and does 'למדו' fit the past tense here?", hint_he: "בדקי אם 'המורות' (נקבה רבים) מתאים לצורת הפועל 'לימדו' מבחינת מין, מספר וזמן.", explanation_en: "The subject 'המורות' is feminine plural, and the verb 'לימדו' is the past-tense form that works for plural subjects (masculine or feminine alike, since Hebrew past-tense plural verbs don't distinguish gender — e.g. 'הם למדו' / 'הן למדו'). The tense (past) matches the context, the verb is present in the sentence, and 'את הילדות' correctly marks the definite direct object. Since subject-verb agreement, tense, and sentence completeness all check out, the sentence is grammatically correct — so the answer is א, כן נכון." },
  { id: 'fc67fc17-e843-4291-80f2-a7a65091be2f', hint_en: "Check the noun's gender and number first — כלבים is masculine plural, so the adjective must match that form.", hint_he: "בדקו מין ומספר של שם העצם — כלבים הוא זכר רבים, וגם שם התואר חייב להתאים.", explanation_en: "The noun כלבים is masculine plural (ends in ים). Adjectives in Hebrew must agree with the noun in gender and number, so the masculine plural form of גדול is required: גדול+ים = גדולים. The other options are wrong because גדול is singular, גדולה is feminine singular, and גדולות is feminine plural — none match a masculine plural noun." },
  { id: '0906af23-22f0-41c7-a053-497a94c50f78', hint_en: "Ask which word names a thing (person/animal/object) and which word tells an action being done — 'flew high' describes what the bird is doing.", hint_he: "שאלו איזו מילה מציינת דבר (חיה/עצם) ואיזו מציינת פעולה — 'עפה גבוה' מתאר מה הציפור עושה.", explanation_en: "ציפור (bird) names a living creature, so it's a שם עצם (noun). עפה (flew/flies) tells the action the bird is doing, so it's a פועל (verb) — it changes form with tense/person (עפה, עף, עפתי), which nouns don't do. גבוה (high) describes how she flew, not a noun or the verb itself, so option א is correct." },
  { id: '1676fd8c-b97c-4d38-9129-d6cc690c0f7f', hint_en: "Think about how masculine present-tense verbs change for feminine singular — what letter is added at the end?", hint_he: "חשבו איך פועל בהווה בזכר משתנה לנקבה יחיד - איזו אות מתווספת בסוף?", explanation_en: "כותב is masculine singular present tense. To make it feminine singular, add the suffix ת at the end: כותב + ת = כותבת. (כותבים is masculine plural, כותבות is feminine plural, and כותבה is not a real word.)" },
  { id: '1d6ea0e6-cf90-46ea-8a8f-1763deadfc9f', hint_en: "Look at the subject הבנות - it's feminine plural. The verb needs to match its gender and number, not just the tense.", hint_he: "הסתכלו על הנושא הבנות - זה נקבה רבות. הפועל צריך להתאים במין ובמספר.", explanation_en: "The subject הבנות is feminine plural, so the verb מלשחק in present tense must take the feminine plural ending ־ות: משחק+ות = משחקות. The other options don't match: משחק is masculine singular, משחקים is masculine plural, and שיחקה is feminine singular past tense." },
  { id: '1ddcfdb1-ae77-4b1f-8cff-e33cd460c3d0', hint_en: "Check the ending of כיסא — words without a feminine ending like ה or ת are usually masculine.", hint_he: "בדקו את הסיומת של כיסא — מילים בלי סיומת נקבה כמו ה או ת הן בדרך כלל בזכר.", explanation_en: "כיסא ends in א, not in a typical feminine ending like ה or ת (as in כיתה or דלת). Since it lacks a feminine marker, כיסא is masculine — we say כיסא גדול (not גדולה), confirming זכר is correct." },
  { id: '1f05659f-7cb7-4713-84dd-9d5e55c00a8c', hint_en: "Check each option: can you put 'a' or 'the' in front of it and picture it as a thing? Verbs show action and adjectives/adverbs describe, so rule those out first.", hint_he: "בדקו כל מילה: אפשר לשים לפניה 'ה' ולדמיין אותה כדבר? פעלים מתארים פעולה ותארים/תוארי פועל מתארים איכות, אז אפשר לפסול אותם קודם.", explanation_en: "'Flower' is a person, place, or thing — it names an object you can see and touch, so it's a noun. Check the others: 'run' names an action (a verb), 'happy' describes how someone feels (an adjective), and 'quickly' describes how an action is done (an adverb). Since only 'flower' names a thing, it's the noun." },
  { id: '36957f2b-ce11-449b-a41d-28f5b918ebb3', hint_en: "ספר is a masculine noun — think about the ending masculine plural nouns usually take in Hebrew.", hint_he: "ספר הוא שם עצם זכר - חשבו איזה סיומת מקבלים שמות עצם בזכר ברבים.", explanation_en: "ספר (sefer) is a masculine noun, and masculine nouns in Hebrew form their plural by adding the ending ים- to the singular. So ספר + ים = ספרים. The other options use wrong endings or aren't plural forms: ספרות looks like a feminine plural pattern, ספרה and ספרן are different words entirely, not plural forms of ספר." },
  { id: '3cea8a81-dedf-420b-9b8e-68135fe87321', hint_en: "Ask yourself: what is the girl doing? The word that describes her action changes based on who's doing it and when — that's the verb.", hint_he: "שאלו את עצמכם: מה הילדה עושה? המילה שמתארת את הפעולה, ומשתנה לפי מי עושה אותה ומתי, היא הפועל.", explanation_en: "In the sentence הילדה כותבת שיעורים, ילדה is the noun (the doer, a person), שיעורים is the noun (the object, the thing being written), and כותבת is the verb — it describes the action happening (writing) and matches the girl in gender/number (feminine, singular), a key sign of a verb in Hebrew. So the correct answer is כותבת." },
  { id: '4fd0e330-ea74-4f16-afe8-de0d1835bc64', hint_en: "Check each option for a naming word (person/animal/thing) and an action word — the other choices are missing one of these.", hint_he: "בדקו בכל אפשרות אם יש מילת שם (מי/מה) ומילת פעולה – בשאר האפשרויות חסר אחד מהם.", explanation_en: "\"The bird\" names a thing (noun), and \"sings\" tells what it does (verb), so this option has both. The other options are just descriptive phrases: \"big and blue\" and \"very quickly\" are adjective/adverb pairs with no noun or verb naming a subject and action, and \"slowly running\" pairs an adverb with a verb form but has no noun to act as the subject." },
  { id: '52169b63-05e9-4aba-8584-18580501fac8', hint_en: "Check if the subject הילדים is masculine plural, then find the verb form that matches that gender and number - it should end in ים.", hint_he: "בדקו אם הילדים הוא זכר רבים, וחפשו את צורת הפועל המתאימה - היא צריכה להסתיים ב-ים.", explanation_en: "The subject הילדים is masculine plural, so the verb must agree in gender and number, taking the masculine plural present-tense ending ים: ר-ץ + ים = רצים. The other options fail to match: רצות is feminine plural (ות ending), רצה is feminine singular, and רוצה is singular (mixed gender), so none agree with the plural masculine subject הילדים." },
  { id: '5fe4d331-8595-4592-808f-8ebc2b2f9037', hint_en: "Ask which word tells what someone is doing, not the name of an object — try adding 'הוא' before each word and see which one makes sense as an action.", hint_he: "שאל איזו מילה מתארת מה מישהו עושה, ולא שם של חפץ - נסה להוסיף 'הוא' לפני כל מילה ובדוק איפה זה מתאים.", explanation_en: "כיסא (chair), שולחן (table), and ספר (book) are all names of objects (nouns) - they answer the question 'what is it?'. רץ (runs) tells what someone is doing - you can say 'הוא רץ' (he runs), which describes an action. That's why רץ is the action word (פועל)." },
  { id: '693a2685-ed60-4d0b-9b53-404789dee9e2', hint_en: "A noun names a person, animal, place, or thing — look for the word that names a living creature, not an action word.", hint_he: "שם עצם הוא מילה שמציינת אדם, בעל חיים, מקום או דבר - חפשו את המילה שמציינת יצור חי, ולא מילה שמתארת פעולה.", explanation_en: "In the sentence הכלב שותה מים, שותה is a verb (it describes the action of drinking) and מים is also a noun, but כלב is the noun that names the animal doing the action - the subject of the sentence. Since the question asks for 'the noun' as a single answer and כלב is the one naming the living creature performing the verb, כלב is the correct choice." },
  { id: '6c2db724-3cd5-45ab-8cad-0cae9815a70c', hint_en: "Nouns name a person, animal, place, or thing — verbs describe an action being done. Check which word doesn't describe someone 'doing' something right now.", hint_he: "שם עצם הוא שם של אדם, בעל חיים, מקום או דבר — לעומת פועל שמתאר פעולה. בדוק איזו מילה לא מתארת מישהו שעושה משהו כרגע.", explanation_en: "רץ, קופץ, and שוחה all describe an action someone is doing right now (running, jumping, swimming) — these are verbs in present tense form. חתול, however, names an animal — it doesn't describe any action, so it's the noun." },
  { id: '743d2ff2-823e-4a34-8094-8896dbfdc28c', hint_en: "Think about how most feminine singular nouns form their plural — what ending do they take instead of the final ה?", hint_he: "חשבו איך בונים רבים לרוב שמות העצם בנקבה - איזה סיומת מחליפה את ה' הסופית?", explanation_en: "ילדה is a feminine noun ending in ה. To form the plural of most feminine nouns, drop the final ה and add the ending ות: ילד(ה) → ילד + ות = ילדות. So the correct plural is ילדות." },
  { id: '7cf17ca9-5eee-451e-b27c-ced177302a85', hint_en: "Ask yourself: can you put 'the' in front of it, like 'the ___'? Nouns name things; verbs starting with ל usually name actions.", hint_he: "בדוק אם אפשר לשים 'ה' לפני המילה, כמו 'ה־אוכל'. שמות עצם מציינים דבר, ופעלים שמתחילים ב-ל מציינים פעולה.", explanation_en: "A noun names a person, place, or thing, while a verb in the infinitive form in Hebrew typically starts with the letter ל (like לאכול, ללכת, לשתות). Here, אוכל means 'food' — a thing you can point to, count, or put 'the' before ('the food') — so it's a noun. לאכול means 'to eat', an action, and its ל- prefix marks it as a verb in the infinitive. So the correct answer is אוכל." },
  { id: '820c205a-e700-4073-adb6-a142c008fe67', hint_en: "Think about how nouns for people usually change for plural, and remember that מורה can describe either a man or a woman — each form has its own ending.", hint_he: "חשבו איך שמות עצם המתארים אנשים משתנים ברבים, וזכרו שמורה יכול להיות גם מורה וגם מורה — לכל אחד יש סיומת אחרת.", explanation_en: "מורה is a noun for a person, so its plural depends on whether it refers to a male or female teacher. For a male teacher, the ending ה is dropped and the masculine plural suffix ים is added: מורה → מורים. For a female teacher, the ה is replaced with the feminine plural suffix ות: מורה → מורות. Since מורה can mean either, both מורים and מורות are correct plural forms, making 'מורים / מורות' the right answer." },
  { id: '87fe664e-2802-4e48-b625-7302210ed497', hint_en: "In each option, check if there's a word naming a person/thing (noun) AND a separate word showing an action the person does (verb) — not just a description.", hint_he: "בכל אפשרות בדקו אם יש מילה שמציינת אדם או דבר (שם עצם) וגם מילה שמראה פעולה שהוא עושה (פועל) — ולא רק תיאור.", explanation_en: "A noun names a person, animal, or thing, and a verb describes an action. In 'הילד רץ' - 'הילד' (the boy) is a noun naming a person, and 'רץ' (runs) is a verb describing what he does - so this sentence has both. Checking the others: 'הילד גדול' has the noun 'הילד' but 'גדול' (big) is an adjective, not an action. 'מהר מאוד' (very fast) has no noun at all - both words describe manner. 'ספר כחול' has the noun 'ספר' (book) but 'כחול' (blue) is an adjective, not a verb. Only 'הילד רץ' contains both a noun and a verb." },
  { id: '919ea4f5-654f-4795-8197-706e5bc146f2', hint_en: "ילד is a masculine noun — think about the ending most masculine plural nouns take in Hebrew.", hint_he: "ילד הוא שם עצם זכר — חשבו איזה סיומת מקבלים רוב שמות העצם בזכר רבים.", explanation_en: "ילד is a masculine singular noun, and most masculine nouns in Hebrew form their plural by adding the ending ים (dropping any vowel changes aside). So ילד + ים = ילדים. The other options are wrong forms: ילדות and ילדה use the feminine endings ות/ה, and ילדן means 'kindergarten', not a plural." },
  { id: 'a1cc5406-5fb4-4093-8ba0-80bd4424db9d', hint_en: "Try putting 'I can ___' in front of each word — only the action word will make sense in that blank.", hint_he: "נסו להשלים 'אני יכול/ה ל...' לפני כל מילה — רק מילת פעולה תתאים במשפט.", explanation_en: "A verb names an action someone can do. 'Tree', 'blue', and 'house' name a thing or a quality — you can't 'do' a tree or 'do' blue. But you CAN do the action 'swim' (as in 'I swim'), so swim is the verb." },
  { id: 'a5a274f0-245e-4844-acba-b7955d76daba', hint_en: "Try turning each word into 'He is ___-ing.' Which one refuses to fit that pattern?", hint_he: "נסה להשלים כל מילה במשפט 'הוא ___' - איזו מילה לא מתאימה לתבנית של פעולה?", explanation_en: "רץ, קופץ, and שוחה are all verbs describing what someone is doing (running, jumping, swimming) - you can say 'הוא רץ', 'הוא קופץ', 'הוא שוחה'. שולחן (table) is a noun naming an object; you cannot say 'הוא שולחן' as an action. So שולחן is the word that is not an action." },
  { id: 'c6bac355-351d-4aea-8539-067fc8a34430', hint_en: "Think about whether the word מורה changes its spelling depending on whether the teacher being talked about is a man or a woman.", hint_he: "חשבו האם המילה מורה משתנה בכתיב כשמדובר על מורה גבר לעומת מורה אישה.", explanation_en: "The word מורה has one fixed spelling, but it is used in sentences about both a male teacher ('המורה הסביר') and a female teacher ('המורה הסבירה') — the gender is shown only by the verb or adjective around it, not by the noun itself. Since the same word serves both, the answer is יכול להיות שניהם, not 'always masculine' or 'always feminine'." },
  { id: 'ca007c06-b973-4d39-a120-870539e53240', hint_en: "A noun names a person, animal, or thing — the others describe actions someone is doing right now. Check which word doesn't change based on who is doing it.", hint_he: "שם עצם הוא שם של דבר, בעל חיים או אדם - שאר המילים מתארות פעולה שמישהו עושה. בדקי איזו מילה לא משתנה לפי מי שעושה את הפעולה.", explanation_en: "שולחן (table) names an object — it doesn't describe an action. The other three words are verbs in present tense describing what someone is doing: רץ (is running), קופץ (is jumping), שר (is singing) — each changes form depending on who does the action (רצה, קופצת, שרים), which is a sign of a verb. שולחן stays the same no matter who is near it, so it is the noun." },
  { id: 'd05a7c45-f576-4616-89c4-76d65afd6894', hint_en: "Masculine plural verbs in the present tense usually end with the suffix ים־ — try adding that ending to the base form קורא.", hint_he: "לפעלים בהווה בזכר רבים יש בדרך כלל סיומת ים־ — נסה להוסיף אותה לצורת היחיד קורא.", explanation_en: "The verb קורא is in the present tense, masculine singular form. To make it masculine plural, add the ending ים־ to the base: קורא + ים = קוראים. (The other options are wrong forms: קוראות is feminine plural, קוראת is feminine singular, and קרא is past tense.)" },
  { id: 'd87cdcfa-96ff-4193-8598-04e27fee168a', hint_en: "Ask yourself which word names a person, animal, or thing in the sentence, rather than an action or description.", hint_he: "שאל את עצמך איזו מילה במשפט מציינת אדם, בעל חיים או דבר, ולא פעולה או תיאור.", explanation_en: "In 'The dog runs fast,' 'runs' is the action (verb) telling what the dog does, and 'fast' is a describing word telling how it runs. 'Dog' is the only word naming a person, animal, or thing — that makes it the noun." },
  { id: 'db17999c-c4d4-4015-a727-e9042ed60010', hint_en: "Try adding 'the' or 'a' before each word in your mind - only a noun (a thing) fits naturally that way, unlike words describing an action someone is doing now or did in the past.", hint_he: "נסה להוסיף 'ה-' לפני כל מילה - רק שם עצם (דבר) יתאים, בניגוד למילים שמתארות פעולה בהווה או בעבר.", explanation_en: "שותה and שתה are verbs (forms of the verb לשתות - 'to drink'): שותה is present tense (he drinks/is drinking) and שתה is past tense (he drank). שתייה, on the other hand, names the action/thing itself - 'a drink' or 'drinking' as a concept - and can take a definite article (השתייה) or plural (שתיות) like any noun, which verbs cannot do. That's why שתייה is the noun." },
  { id: 'f420112e-bd24-4b9e-bebe-be431582a580', hint_en: "Ask which word tells what someone is doing, not the name of a thing.", hint_he: "שאלו איזו מילה מתארת מה מישהו עושה, ולא שם של דבר.", explanation_en: "כדור, בית, and ספר are all nouns — they name things (a ball, a house, a book). רץ means 'running/is running,' describing an action someone does, which makes it the verb." },
  { id: 'fc57d10b-c0bc-4879-95db-d72f97ab0e11', hint_en: "A verb tells us an action someone is doing right now — look for the word that describes what someone does, not a thing or a description.", hint_he: "פועל מתאר פעולה שמישהו עושה עכשיו - חפשו את המילה שמתארת מה עושים, לא דבר או תיאור", explanation_en: "כלב (dog) is a noun (name of an animal), ירוק (green) is an adjective describing color, and עיפרון (pencil) is a noun (name of an object). Only שר (sings/is singing) describes an action someone performs — that's what makes it the verb, matching the pattern of פועל בהווה like הולך, אוכל, קורא." },
  { id: '0c7ebe8f-ec22-478a-835d-584a013a2e7e', hint_en: "Think about where the information comes from: is it written in the words themselves, or does the reader have to connect clues to figure it out?", hint_he: "חשבו מאיפה המידע מגיע: האם הוא כתוב במילים עצמן, או שהקורא צריך לחבר רמזים כדי להבין אותו?", explanation_en: "The words 'explicit' and 'implicit' point to two different sources of meaning. Explicit comes from a root meaning 'unfolded/stated openly' — so explicit information is written in the text in plain words, like 'It was raining,' which you can find by simply reading the sentence. Implicit comes from a root meaning 'folded in' — so implicit information is hidden inside details the author gives, and the reader must combine those clues with their own reasoning to reach it, like inferring it rained because a character opens an umbrella and comes in with wet shoes. This matches option B: explicit is stated directly, implicit must be inferred. The other options don't reflect this distinction — explicit information isn't 'false' (A), the explicit/implicit split has nothing to do with title versus body placement (C), and the two clearly differ in how the reader accesses the information (D)." },
  { id: '3be99123-b9a2-4156-b0ab-1cbda399fe99', hint_en: "Think about the difference between story details (setting, characters, title) and the bigger idea the author wants readers to take away.", hint_he: "חשוב על ההבדל בין פרטי הסיפור (מקום, דמויות, כותרת) לבין הרעיון הגדול שהמחבר רוצה שהקוראים יקחו איתם.", explanation_en: "Setting (A), main character (C), and title (D) are all concrete story details you can point to directly in the text, but they aren't what the story is really 'about' in a deeper sense. The theme is the underlying message or lesson the story teaches — for example, a story about a slow tortoise beating a fast hare isn't really about animals racing, it's about the lesson that persistence beats speed. That's why 'The main message or lesson' is correct." },
  { id: '5368b74d-d283-4fe6-85a1-a2ca7098f7bc', hint_en: "Ask what all three sentences have in common — pollination, farming, and food security are all examples of one bigger point. Look for the option that covers the whole passage, not just one detail.", hint_he: null, explanation_en: "Each sentence adds another reason bees matter for food: they pollinate crops, farmers depend on that pollination to grow produce, and this affects food security worldwide. All three details support one umbrella idea — bees' importance to our food supply — which matches C. A and B mention only single details (honey, farmers' effort) that aren't even stated in the passage or aren't the focus, and D isn't mentioned at all." },
  { id: '6aeec0e7-aa2b-4641-9768-475cce1bc7d6', hint_en: "Think about what a metaphor like \"time is money\" actually means — is it true fact-by-fact, or is it making a creative comparison?", hint_he: "חשבו על מטפורה כמו \"הזמן הוא כסף\" - האם זו עובדה מילולית, או השוואה יצירתית?", explanation_en: "A phrase like \"the wind whispered\" doesn't mean wind literally has a mouth and whispers words — it's a creative, non-literal way of describing a soft sound, which is exactly what figurative language is (option B). Option A (only facts) describes literal language, the opposite of figurative. Option C describes spelling out numbers, and option D describes sentence length — neither relates to word meaning at all." },
  { id: 'af41470f-8e61-47c4-997a-23a200a6ef82', hint_en: "Look at what happened right after 'paid off' — the project launched successfully with great reviews. That outcome tells you what the phrase means here.", hint_he: null, explanation_en: "The sentence links 'paid off' directly to a result: the project 'launched successfully and received glowing reviews.' Since this positive outcome followed their tireless work and late nights, 'paid off' must mean that the effort led to success — matching option C. It does not mention money (A), cancellation (B), or vacation (D), so those results contradict the described outcome." },
  { id: 'f52878b8-1996-49fa-b9eb-8488a5e6152d', hint_en: "Ask yourself: what point do almost all the sentences in the text support or connect back to?", hint_he: "שאל את עצמך: לאיזה רעיון רוב המשפטים בטקסט מתחברים או תומכים?", explanation_en: "The main idea is what remains after you strip away the supporting details, examples, and titles — it's the single point that all the sentences in a paragraph or passage work together to support. A detail (A) is just one small piece of evidence, a question (C) doesn't state a point at all, and a title (D) only labels the text without explaining its central point. So the main idea must be 'the most important idea,' since that's the one thing every other sentence in the text is built around." },
  { id: '25856638-1c68-4d99-a222-2ed8f2207149', hint_en: "Reread the sentence and find the exact subject that performs the action 'entered the room.'", hint_he: null, explanation_en: "The sentence says 'רוח קרירה נכנסה לחדר' — the subject of the verb 'נכנסה' (entered) is 'רוח קרירה' (a cool breeze). Bird, rain, and teacher are never mentioned, so only 'a cool breeze' matches the text." },
  { id: '47fd2741-617d-4fb9-953a-a84f42b00d64', hint_en: "Find the subject (who does the action) and the verb ending: הסבירה is a feminine verb agreeing with המורה. Then check who receives the action, marked by the preposition ל־ before תלמידים.", hint_he: "מצא מי מבצע את הפעולה (הנושא) ומי מקבל אותה. שים לב לצורת הפועל הסבירה ולמילת היחס ל־ לפני תלמידים.", explanation_en: "In this sentence, המורה (the teacher) is the subject, and הסבירה (explained) is a feminine singular past-tense verb that agrees with המורה — feminine noun, feminine verb form. The object את השיעור (the lesson) tells us what was explained, and the prefix ל־ on לתלמידים ('to the students') marks the recipient of the explanation. So the structure is: subject (teacher) + verb (explained) + object (the lesson) + recipient (to the students) = 'The teacher explained the lesson to the students.' This matches option B; it cannot be A, since the verb form הסבירה is feminine singular and matches המורה, not the plural תלמידים." },
  { id: '5d058696-ec45-49ac-8ea3-55a8958a9184', hint_en: "Scan the sentence for the specific day and time-of-day phrase, then match those exact words to the answer choices.", hint_he: null, explanation_en: "The sentence states 'every Thursday after school,' which directly gives both the day (Thursday, not Sunday) and the time (after school, not before school, not just summer). Option A matches these two details exactly, so it is correct." },
  { id: '61b778e3-cf77-486a-93da-6732fcea640e', hint_en: "Think about what nikud normally provides that is missing from the text, and how a reader might figure that missing piece out another way.", hint_he: "חשבו מה הניקוד בדרך כלל מספק וחסר בטקסט, ואיך הקורא יכול להשלים את החוסר הזה בדרך אחרת.", explanation_en: "Nikud marks vowels (like the dot for 'i' or 'o'), but unpointed text shows only consonant letters. For example, the letters ס-פ-ר could be read as 'sefer' (book) or 'sapar' (barber) — the letters alone don't tell you which vowels to use. A reader must use the surrounding words and sentence meaning to decide the correct pronunciation, which is why option B, not the number or length of letters/words (A, C, D), explains the challenge." },
  { id: '732414c3-b5bf-4e8e-a2a2-0ead0778b04b', hint_en: "Think about what nikud actually shows on each letter, and what disappears when it's removed.", hint_he: "חשוב מה הניקוד בעצם מראה על כל אות, ומה נעלם כשמסירים אותו.", explanation_en: "Nikud marks the vowel sounds (a, e, i, o, u) attached to each consonant — for example בָּ vs בִּ vs בֹּ are the same letter ב with different vowels. Remove the nikud and the letters ב, ב, ב look identical, so the reader has to figure out which vowel belongs there using context and familiarity with the word — not the letters themselves, which stay the same either way. That's why B is correct, while A, C, and D describe things that don't actually change between pointed and unpointed text." },
  { id: '7f62f733-707d-4da5-a98d-84b7c5a7a482', hint_en: "The sentence lists two actions in order, connected by 'and' — check which verb comes right after 'Before the race' and which comes after the word 'and'.", hint_he: null, explanation_en: "The sentence structure is 'Amir tied his shoes... and stretched his legs,' with 'and' (ו) joining two actions in the sequence they happened. Since 'tied his shoes' appears before 'and stretched his legs,' tying his shoes happened first, making A correct." },
  { id: 'bea8a34e-0545-4a91-9163-223bbe72461c', hint_en: "Look at what the sentence describes from start to finish — rain forming and falling — and match that process to one topic option.", hint_he: null, explanation_en: "The prompt states the article explains 'how rain forms in clouds and falls to the ground.' This is a description of the rain cycle, not plant growth, cloud-building, or bird migration, so the topic matching that description is A, 'How rain forms.'" },
  { id: 'cdac503b-fc2b-42d0-be7b-dec6470320ae', hint_en: "Think about which sky-related noun uses the letters ש-מ-ש — it's also part of the word for 'sunset' (שקיעה relates to daytime, but שמש itself appears in 'שמשיה' - sunshade).", hint_he: "חשבו על מילה הקשורה לשמיים שמורכבת מהאותיות ש-מ-ש - היא גם מופיעה במילה 'שמשייה' (מטריית שמש).", explanation_en: "The unpointed letters ש-מ-ש spell שֶׁמֶשׁ, the Hebrew word for 'sun.' You can recognize it from related words like שמשיה (sunshade/parasol) and שמשי (solar), which all share the same root and refer to the sun — not moon (ירח), star (כוכב), or cloud (ענן)." },
  { id: 'e181b98a-192e-4702-a0b9-6b7024cb62ff', hint_en: "Break the sentence into its three parts: who (הילד), the action (הלך), and where (לבית הספר). Match each piece to an English word before choosing.", hint_he: "פרקו את המשפט לשלושה חלקים: מי (הילד), הפעולה (הלך), ולאן (לבית הספר). התאימו כל חלק למילה באנגלית לפני שתבחרו.", explanation_en: "Break the sentence into its parts: הילד = \"the boy\" (not הילדה, which would be \"the girl\"), הלך = \"went\" (past tense of ללכת, not נשאר/\"stayed\"), and לבית הספר = \"to school\" (not הביתה/\"home\"). Putting the parts together in order — boy + went + to school — gives \"The boy went to school,\" matching option B. The other options each swap in a wrong subject, verb, or destination that doesn't appear in the sentence." },
  { id: 'e90373d0-2084-48fb-93f3-96923c9358dd', hint_en: "Look for the word 'so' — it connects a reason to a result. What comes right before it?", hint_he: null, explanation_en: "The sentence uses 'so' to link cause and effect: 'The museum was closed on Monday SO our class visit was moved.' The part before 'so' (museum closed) is the cause; the part after (visit moved) is the result. Options B, C, and D introduce reasons never mentioned in the sentence, so only A matches the stated cause." },
  { id: 'f60521f2-ddc3-4f7b-98d4-c2e053de4ce9', hint_en: "Find the word 'because' in the sentence — the reason for their action comes right after it.", hint_he: null, explanation_en: "The sentence gives the reason directly with the word 'because': 'the hikers continued climbing because they wanted to reach the waterfall before sunset.' The clause 'the path was steep and rocky' only describes an obstacle they overcame (signaled by 'although'), not their motivation. So the cause of their climbing is stated explicitly as reaching the waterfall before sunset, matching option A. Options B, C, and D aren't mentioned anywhere in the sentence." },
  { id: '215c8f88-e29d-4cb6-bba9-518f30c39675', hint_en: "Think of the Hebrew word 'shemesh' (sun) - which letter repeats at the start and end, making that 'sh' sound?", hint_he: null, explanation_en: "The letter ש (shin) makes the 'sh' sound, as in שמש (shemesh, sun) or שלום (shalom, peace). The other letters make different sounds: ב makes 'b' or 'v', כ makes 'k' or 'kh', and ת makes 't'. So ש is the only one matching 'sh'." },
  { id: '435ae429-449d-470c-8a7a-406188bd1341', hint_en: "Think about what nikud (vowel marks) normally tell the reader, and what happens when they're missing.", hint_he: null, explanation_en: "Nikud marks (like patach, kamatz, chirik) show which vowel sound follows each consonant. Hebrew letters themselves are mostly consonants, so without nikud a word like ספר could be sefer, sapar, or sapper - the reader must guess the vowels from context and vocabulary knowledge. That's why option B is correct: the difficulty comes from missing vowel-sound cues, not letter size, word count, or reading direction." },
  { id: 'cf847bc6-4a67-4057-841c-3897d5f13e58', hint_en: "Think about what happens when you say each letter's sound one after another, faster and faster - what forms?", hint_he: null, explanation_en: "When you sound out letters one by one (like m-a-t) and then blend those sounds together quickly (mat), the separate sounds merge into a whole word you can recognize and read. This blending skill is not for drawing, singing, or handwriting - it turns individual letter sounds into readable words, which is why the answer is B." },
  { id: 'd4dacc4b-e9c3-4304-985c-12e362fcd190', hint_en: "Say each letter's name out loud and listen for which one starts with the 'mmm' sound — think of a word like 'מים' (water).", hint_he: null, explanation_en: "The letter מ (mem) makes the 'm' sound, as in the word מים (water) or אמא (mother), where you hear 'mmm' at the start. The other letters make different sounds: נ (nun) sounds like 'n', ל (lamed) sounds like 'l', and ס (samech) sounds like 's' — none of these match the 'm' sound asked for." },
  { id: 'd4e5a823-7be3-404e-86e2-5a075b6fdfcf', hint_en: "Say each letter's name out loud and listen for which one starts with the 'l' sound, like in the word 'lamed'.", hint_he: null, explanation_en: "The letter ל is called 'lamed,' and its name begins with the sound 'l' - that's the sound it makes in words. The other letters have different sounds: מ makes 'm' (mem), נ makes 'n' (nun), and ד makes 'd' (dalet). So ל is the one that makes the 'l' sound." },
  { id: 'dab2e244-b43d-4cac-abdb-4aca03eccc13', hint_en: "Think about the order you learn Hebrew letters: alef, bet, gimel... which one is said first?", hint_he: null, explanation_en: "The Hebrew alphabet order begins: א (alef), then ב (bet), ג (gimel), ... all the way to ת (tav) at the end. Since א is recited first, it comes before ב, ל, and ת — so C (א) is correct." },
  { id: 'e9723883-5401-4f7e-8003-4d4b6706cc4a', hint_en: "Think about the two possible sounds the letter ב can make — a soft sound like 'v' and a hard sound like 'b'. What does the dot inside it signal?", hint_he: null, explanation_en: "The letter ב has two pronunciations: without a dagesh it sounds soft, like 'v' (as in ורד), but when a dot (dagesh) is placed inside it, it becomes hard/strong and is read as a regular 'ב' sound, like 'b' (as in בית). So a dagesh in ב doesn't change it to 'פ', make it silent, or double it — it simply marks the strong 'b' sound, which matches option B." },
  { id: 'ebf99f37-7bfa-4c1b-bae9-aec82ea80f3b', hint_en: "Think about which side of the page Hebrew books start from, and which way your eyes move across the letters as you read a word like אבא.", hint_he: null, explanation_en: "Hebrew letters are written and read starting from the right side of the page and moving toward the left — for example, the word אבא is read by starting at the א on the right, then the ב in the middle, then the א on the left. This matches option B, מימין לשמאל (from right to left). Option A describes English-style reading, C describes reading top to bottom (like some other writing systems), and D is not a real rule." },
  { id: '1e415018-1eca-4d7a-a389-f0928a8908d3', hint_en: "Think about what strategy actually uses the sentence around a tricky word, rather than outside help or avoidance.", hint_he: null, explanation_en: "Context clues means using the words and sentences surrounding an unfamiliar word to figure out its meaning, so option B matches the definition exactly. Options A, C, and D describe other strategies (dictionary use, asking someone, ignoring the word) that don't involve reading the surrounding text at all, so they don't fit the term 'context clues.'" },
  { id: '2801b967-027c-4b4b-9e8f-0dc2f7980540', hint_en: "Think about whether you can point to the exact words on the page, or whether you have to use clues plus your own reasoning to figure it out.", hint_he: null, explanation_en: "Explicit information is stated directly in the text using clear words — for example, a sentence that says 'It was raining.' Implicit information is not written outright; the reader must combine text clues with background knowledge to infer it — for example, a character grabbing an umbrella and boots implies it's raining, even though the text never says so. This distinction (directly stated vs. suggested/inferred) matches option A, while B, C, and D describe things that aren't true about these terms — implicit ideas aren't automatically true or false, the two clearly differ, and both apply across science and stories alike." },
  { id: '4117b6a9-541f-4f43-8298-ce425b447c1e', hint_en: "Break the word apart: 'context' means the surrounding text, so think about what surrounds an unfamiliar word.", hint_he: "פרקו את המילה: 'הקשר' מתייחס לטקסט הסובב, אז חשבו מה מקיף מילה לא מוכרת.", explanation_en: "The word 'context' refers to the surrounding text — the sentences and words near a word. So a 'context clue' is a hint found in that surrounding text, not from an outside source like a dictionary (A) or a teacher (C), and not the title (D). Option B correctly identifies this: the words around an unknown word that help reveal its meaning, which is exactly how readers use context to figure out unfamiliar vocabulary." },
  { id: '47dd7260-ece3-4b17-b6d3-2cb005a56846', hint_en: "Look at the pronouns the narrator uses to refer to themselves in the sentences.", hint_he: null, explanation_en: "First person point of view is identified by the pronouns used, not by content or formatting. A first-person narrator refers to themselves using words like I, me, my, and we — for example, 'I walked to the store' shows the narrator speaking directly about themselves. He/She (option A) signals third person instead, and options C and D describe unrelated features that have nothing to do with point of view." },
  { id: '5a449c16-da38-40bc-bb00-01e247ee30e8', hint_en: "Think about why the author wrote the paragraph — what point are all the details supporting?", hint_he: null, explanation_en: "The main idea is not a physical feature like word count or a name list (options A, C, D describe form, not meaning) — it's the key point the details in the paragraph all work together to support. Since only option B describes that kind of central message rather than a countable or literal text feature, B is correct." },
  { id: '911cfc30-789d-47d8-904e-9bca00d7b4f4', hint_en: "Think about which sentence a reader needs first in order to understand all the sentences that follow it.", hint_he: null, explanation_en: "A topic sentence states the main idea that every other sentence in the paragraph will explain or support. For readers to make sense of those supporting details as they read, the main idea must be given to them first — so writers place the topic sentence at the beginning, before the supporting details in the middle and the concluding thought at the end." },
  { id: '93f6e564-466e-494c-a797-14398a5e3358', hint_en: "Try summing up the paragraph in one sentence — the main idea is the point that all the details support, not a single detail or one sentence.", hint_he: "נסו לסכם את הפסקה במשפט אחד — הרעיון המרכזי הוא הנקודה שכל הפרטים תומכים בה, לא פרט בודד או משפט אחד.", explanation_en: "A paragraph is usually built from one central point plus several supporting details that explain or prove it. The last sentence (A) might just wrap up the paragraph, not capture the whole point; individual details (C) are pieces of evidence, not the overall message; and a title (D) is a separate label for the whole passage, not something every paragraph even has. Since every sentence in a paragraph works together to support one key point, the main idea is that overall point — option B." },
  { id: 'ca4f0f00-57d9-4fa8-b1a0-514d0ca980e6', hint_en: "Look for the sentence that introduces the general claim, then check if the other sentences just add details to support it.", hint_he: "חפש את המשפט שמציג את הטענה הכללית, ובדוק אם שאר המשפטים רק מוסיפים פרטים התומכים בו.", explanation_en: "The first sentence, 'Dogs make great pets,' is the general claim the passage is making. The second sentence lists loyal, friendly, and easy to train — these are specific details that explain *why* dogs make great pets, so they support the main idea rather than being the main idea themselves. Since options A, B, and D are each just one of those supporting details, only C captures the overall point of the whole passage." },
  { id: 'd66d6706-310a-48d0-977d-28e3e76bd9d6', hint_en: "Three of these words introduce a cause or reason; only one introduces a result that comes after it. Ask which word could start a new sentence describing what happened next.", hint_he: null, explanation_en: "Because, Since, and Due to all point backward to a reason or cause (e.g., 'Because it rained, the game stopped' — the cause comes right after the word). Consequently works the opposite way: it starts a new statement that follows the cause and names the result, as in 'It rained heavily; consequently, the game was cancelled.' Since only Consequently introduces the effect rather than the cause, C is correct." },
  { id: 'f977e795-7c9c-425f-b890-16148f469352', hint_en: "Think about the job a detail does in a paragraph — does it state the topic, or does it back it up with evidence?", hint_he: "חשבו מה התפקיד של פרט כזה בפסקה - האם הוא קובע את הנושא, או שהוא מספק ראיות לתמיכה בו?", explanation_en: "A paragraph has one main idea plus sentences that support it. The main idea itself is answer A, a conclusion (C) wraps up the passage, and a question (D) is a rhetorical device — none of these back up anything. A supporting detail is a fact, example, or piece of evidence added specifically to explain or prove that main idea, which matches option B." },
  { id: '00317556-144d-438a-9a86-8fa8361d55cf', hint_en: "Think about what 'fluency' (שטף) describes in reading — it's not about learning new words or other skills, but about *how* the reading itself sounds and flows.", hint_he: null, explanation_en: "The word 'שוטף' (fluent) describes the quality of the reading act itself, not related skills. Options A, C, and D describe other language activities (vocabulary, writing, drawing), not reading fluency. Fluent reading is defined by three traits: קצב (pace — reading at a natural speed, not too slow or choppy), דיוק (accuracy — reading the words correctly), and הבעה (expression — using intonation that reflects meaning). Since option B names exactly these three traits, it matches the definition of reading fluency, making it the correct answer." },
  { id: '0ca66185-232f-42e1-8182-09cfb2b9250a', hint_en: "Think about what 'context' actually means when reading — it's not a tool like a dictionary or a person, it's something in the text itself.", hint_he: null, explanation_en: "התשובה היא C כי 'הקשר' (context) פירושו המילים והמשפטים הסובבים את המילה הלא מוכרת - הן נותנות רמזים למשמעותה. לכן, כשנתקלים במילה לא מוכרת, קוראים טוב מסתכלים על המילים מסביבה כדי לנחש את פירושה, במקום לדלג עליה (B), לחפש במילון (A) או לשאול מישהו (D) - אלו הן אסטרטגיות אחרות, אך הן אינן משתמשות ב'הקשר' עצמו." },
  { id: '0d08c09d-94e0-401b-a068-cd17514bb330', hint_en: "Find the word that describes the color of the bag (תיק) in the second sentence, and match it to its English meaning.", hint_he: null, explanation_en: "The second sentence says 'היא לקחה איתה תיק אדום' — 'she took with her a red bag.' The word 'אדום' means 'red,' so the bag's color was red, matching option B." },
  { id: '14ab5925-342c-4503-abcd-497aacfd6e9e', hint_en: "Look for the word that means a drink in the second sentence — the verb 'שתתה' (drank) tells you what to find right after it.", hint_he: null, explanation_en: "The second sentence says 'היא שתתה חלב' — 'she drank milk.' The word 'חלב' means 'milk' in English, so the answer is C, not any of the other drinks listed." },
  { id: '42a80b4f-3b7e-4024-b2b6-64807251d262', hint_en: "Find the word in the sentence that tells you when the running happened — it's a school-related time word.", hint_he: null, explanation_en: "The sentence states directly: 'הילדים רצו למגרש בהפסקה' — 'the children ran to the playground בהפסקה (during recess).' The word 'בהפסקה' is the time clue, and it matches option B, 'During recess.' None of the other choices (night, morning at home, after dinner) appear anywhere in the text." },
  { id: '44bb38ad-dbe9-4d8e-9201-37e936351d3c', hint_en: "Look for the Hebrew word for the piece of furniture in the first sentence — it tells you where the cat is.", hint_he: null, explanation_en: "The first sentence says 'החתול הקטן ישן על הספה' — 'ישן על' means 'sleeps on', and 'הספה' means 'the sofa'. So the cat is sleeping on the sofa, matching option C. The other options (bed, chair, under the table) don't appear in the text at all." },
  { id: '48c5ba41-a4a5-487f-8cec-04e1cb5b98b8', hint_en: "Look at the first sentence and find the word right after 'ציירה' (drew) — that word names the object.", hint_he: null, explanation_en: "The first sentence is 'שרה ציירה שמש גדולה' (Sarah drew a big sun). The verb 'ציירה' (drew) is followed directly by the noun 'שמש' (sun), telling us exactly what she drew. The second sentence only adds that she colored it yellow — it doesn't change what the object is. So the answer is C, a sun." },
  { id: '5b3a7e74-1f14-4da4-acb6-66ad93f73f2d', hint_en: "Find the word 'נדנדה' in the first sentence — that's the item being described as new.", hint_he: null, explanation_en: "The first sentence states 'בגן יש נדנדה חדשה' (in the yard there is a new swing). The word 'נדנדה' means swing, and 'חדשה' (new) directly describes it — so the new item is the swing, answer B." },
  { id: '62d7a74b-850a-4245-8792-df2a5792027c', hint_en: "Think about what the word 'מדויקת' (accurate) means — it's about correctness, not speed or skipping.", hint_he: null, explanation_en: "The word 'מדויקת' comes from the root meaning 'precise/exact.' Applied to reading, precision means every single word is recognized and read correctly as written — not fast (A), not skipped (D), and not about understanding big ideas, which is comprehension, not accuracy (C). So B, identifying each word correctly, matches the meaning of 'accurate.'" },
  { id: '765eeb22-fe29-460a-ab85-7224bdec5ed1', hint_en: "Look at the second sentence and find the subject of the word 'נשארת' (stays) — who is doing that action?", hint_he: null, explanation_en: "The second sentence states 'אמא נשארת בבית עם התינוק' — the verb 'נשארת' (stays, feminine form) has 'אמא' (Mom) as its subject, right before it. Dad is named only in the first sentence as the one who drives to work, so he is not staying home; Grandma and the teacher are not mentioned at all. Therefore Mom is the one staying home with the baby, matching option C." },
  { id: '77978b37-5788-4d80-9a4a-0174e6635a42', hint_en: "Look at the first sentence and find which fruit is described right next to the word 'ירוק' (green).", hint_he: null, explanation_en: "The first sentence, 'על השולחן יש תפוח ירוק,' places the word ירוק (green) directly next to תפוח (apple) — meaning the apple is green. The second sentence only says a banana is nearby, without naming its color, so the answer is B: Apple." },
  { id: '81f7c6f9-1174-40fb-8419-bbb08c5326c0', hint_en: "Look at the first sentence and find the word that names a location — the one after 'בחצר' means 'in the yard.'", hint_he: null, explanation_en: "The first sentence, 'נועם משחק בכדור בחצר,' contains the word 'בחצר' (in the yard). The prefix 'ב-' means 'in,' and 'חצר' means 'yard' — so this word tells us the location where Noam is playing. The second sentence talks about his brother standing by the gate, which doesn't answer the question. So the answer is A, 'In the yard.'" },
  { id: 'cbbe8016-da3c-4125-bd78-31d27b5f5e65', hint_en: "Think about the normal Hebrew word order for a simple sentence: who does the action (subject), then the action (verb), then what receives the action (object).", hint_he: "חשוב על סדר המילים הרגיל במשפט פשוט: קודם מי עושה את הפעולה (הנושא), אחר כך הפעולה (הפועל), ואז מה מקבל אותה (המושא).", explanation_en: "A basic Hebrew sentence follows Subject–Verb–Object order: הילד (subject) אוכל (verb) תפוח (object) — 'The boy eats an apple.' The other options break this order: ב and ד put the object (תפוח) before or mixed into the subject phrase, and ג puts the verb before the subject, which sounds unnatural. Only הילד אוכל תפוח follows the correct, natural word order." },
  { id: 'e2e3838c-ad35-4926-8511-c9816e6e2dd2', hint_en: "Look at the subject of the first sentence — who is the one doing the sitting and reading?", hint_he: null, explanation_en: "The first sentence, 'יואב יושב בכיתה וקורא ספר,' has Yoav as its subject, with 'קורא ספר' (reading a book) describing his action. The second sentence only tells us the teacher smiles at him — it doesn't say she reads. So the one reading the book is Yoav (B)." },
  { id: 'ff9546a7-fd75-43f1-a06d-2798a723767c', hint_en: "Think about two separate skills in reading: one is about turning letters/symbols into words, the other is about grasping what those words mean together.", hint_he: null, explanation_en: "These are two distinct reading skills. Decoding (פענוח) is the technical step of turning written letters into recognizable words — for example, sounding out ילד as 'yeled'. Comprehension (הבנה) happens after that: it means understanding what the words mean together, like knowing that 'הילד רץ הביתה' describes a boy running home. A reader can decode a sentence perfectly (say every word correctly) yet still fail to understand its meaning, which shows the two skills are different. This matches option B and rules out A (there is a difference), C (difficulty isn't the distinguishing feature described), and D (comprehension is about meaning, not writing)." },
  { id: '0ea917e9-a5d3-4281-a17c-f6fab50e7bc2', hint_en: "Look at the second sentence — it tells you what caused the kite's flight, not just what happened.", hint_he: null, explanation_en: "The passage has two sentences: one tells what happened (the kite flew high), and the next explains why (the wind was very strong). Wind is what lifts and carries kites, so the strong wind described right after is the cause. The other options — magic, someone throwing it, short trees — are never mentioned in the text, so they can't be the reason given." },
  { id: '51df6565-49d6-45c0-b0d6-4935ff4623ed', hint_en: "Find the word 'it' in the second sentence and check what noun it stands for in the first sentence.", hint_he: null, explanation_en: "The first sentence names the object: 'a big red ball.' The second sentence says she plays with 'it,' and 'it' refers back to that same ball — so the answer is B, not the other items which are never mentioned." },
  { id: '89d45160-bb48-480e-a04a-ef60adb9ca87', hint_en: "Look at the first sentence — it usually tells you the main idea, while the second sentence just adds supporting details.", hint_he: null, explanation_en: "The first sentence, 'Dogs make great pets,' states the main idea directly. The second sentence, 'They are loyal and fun to play with,' gives supporting details that explain why dogs make great pets — it doesn't introduce a new idea. Options A, C, and D aren't mentioned anywhere in the text, so B is the only idea the passage actually supports." },
  { id: 'af4ff2f5-94c1-44b8-afec-481b6d8bbcad', hint_en: "Read each option aloud and check if the word order matches how we normally speak: who did what, and where. Only one option follows this natural order.", hint_he: null, explanation_en: "In English, a sensible sentence follows subject-verb-place order: 'The cat' (who) + 'sat' (action) + 'on the mat' (where). Option A follows this pattern exactly, so it reads naturally. Options B, C, and D scramble the same words into orders that don't match how English sentences are built, so they sound like nonsense even though they use the same five words." },
  { id: 'b3c272ec-4f95-499c-98ee-d9fb86a22fa9', hint_en: "Find the word that describes how the dog ran, and think of another word that means the same thing.", hint_he: null, explanation_en: "The sentence tells us how the dog ran: 'fast.' The word 'fast' means the same thing as 'quickly,' so option B matches. Options A, C, and D describe things the sentence never mentions (slow, eating, sleeping), so they don't match what the sentence says." },
  { id: 'cb2e3385-2f70-4018-9048-52482fe63efa', hint_en: "Think about how a bird moves when it is up in the sky — which action word matches that?", hint_he: null, explanation_en: "The sentence tells us the bird is 'in the sky,' so the missing word must describe how birds move there. Runs, swims, and sleeps don't match being in the sky, but 'flies' does — that's how birds travel through the air. So B is correct." },
  { id: '4d45e763-d577-417b-aaaf-4d86b94b0a87', hint_en: "Think about the order of a story's structure: beginning, middle, end — what does the beginning need to set up before any problem can happen?", hint_he: null, explanation_en: "Story structure follows an order: beginning (setup), middle (problem/events), end (resolution). Before a problem can occur or be solved, readers need to know who is in the story and where it takes place — that's why introducing characters and setting comes first, at the beginning. The problem, twist, and ending all happen later, once the reader already knows who and where." },
  { id: '61aa3e35-6ab5-4934-8384-9cbc249646fe', hint_en: "Look at the first sentence — it usually states what is wrong before the story explains how it gets fixed.", hint_he: null, explanation_en: "The story's first sentence says 'Tom could not find his backpack' — this is the problem, and the rest of the story ('He looked everywhere and finally found it under his bed') shows how it was solved. Options A, C, and D never appear in the text, so they can't be the problem." },
  { id: '6417217a-395a-46e8-ab05-9ac0169d78a5', hint_en: "Look at the first sentence — it names her feeling before the word 'But' introduces a change.", hint_he: null, explanation_en: "The passage states 'Lily was nervous about her first day of school' — this describes her feeling at the start. The word 'But' that follows signals a change, showing that making a friend happened after and improved how she felt, so 'nervous' is her initial feeling, not 'happy' or 'excited'." },
  { id: '66536842-2750-48b2-afa3-bb06e5239033', hint_en: "Think about the story's main focus — who is it centered on, and does that match one of the options?", hint_he: null, explanation_en: "The word 'protagonist' comes from Greek, meaning the first or leading actor in a story — the character whose goals and actions drive the plot forward. That description matches option B, 'the main character.' The other options name different story roles: the villain (A) opposes the protagonist, the narrator (C) tells the story but may not be its focus, and a side character (D) plays only a supporting part." },
  { id: '72b4fdcd-77a8-4b6b-96eb-6a7e177dba10', hint_en: "Think about the two clues authors give at the start of a story: a location word and a time word — which option matches both?", hint_he: null, explanation_en: "Option C fits because 'setting' combines two things: WHERE (the location, like a forest or a school) and WHEN (the time, like morning or long ago). The other options describe different story parts: A names a person (character), B names a conflict (plot problem), and D names the story's conclusion — none of these tell you the place or time, so C is the only one that matches the definition of setting." },
  { id: '7ac4b644-123a-4a15-aa34-82d0936fd6cf', hint_en: "Think about what each word separately asks you to do: one word points to alikeness, the other to difference.", hint_he: null, explanation_en: "\"Compare\" means to look at two things and find how they are alike, while \"contrast\" means to look at how they are different. Put together, \"compare and contrast\" means examining two things for both their similarities and their differences — which matches option C, not counting characters, rhyming, or identifying setting." },
  { id: 'afb0542f-4849-4a69-8eae-6f8b079ec33d', hint_en: "Think about story order: first there's a problem, then something happens at the end to fix it. Which option matches that 'fixing' part?", hint_he: null, explanation_en: "Stories usually follow a pattern: characters and setting are introduced, then a problem (conflict) appears, and finally the solution shows how that problem gets fixed by the end. Option A describes the story's opening, B names a character, and D describes a mood or scene — none of these involve fixing anything. Only C, 'how the problem gets fixed,' matches what 'solution' means in a story." },
  { id: '45722792-cdaa-4658-99c4-f1ca1e1165aa', hint_en: "Think about a story's shape: it builds up tension step by step. Where in that build-up does the word 'climax' point to?", hint_he: "חשבו על מבנה הסיפור: המתח הולך ונבנה בהדרגה. לאיזה שלב בבנייה הזו מתייחסת המילה 'שיא'?", explanation_en: "A story typically builds tension gradually: exposition (introducing characters/setting) → rising action → climax → resolution. The climax is specifically the peak of that rising tension, the moment of greatest excitement or conflict, right before things start resolving. That's why it's not the beginning (A) or the introduction of characters (D), which happen before tension builds, and not the conclusion (C), which happens after the peak has passed." },
  { id: '57433184-1369-4493-8c6b-988bdb4c7f61', hint_en: "Think about what happens when a line comes back again and again — how does it affect the poem's sound and what it makes you focus on?", hint_he: null, explanation_en: "The line 'Still the sea returns' closes every stanza, so each time the poem shifts to a new scene or feeling, the reader is pulled back to that same image of the sea. This repeated return does two things at once: it stamps the idea of the sea's constancy as central to the poem's meaning, and it creates a predictable beat that gives the poem rhythm, like a refrain in a song. That matches option A. Options B and C would require the repetition to obscure meaning, but a repeated, clear line does the opposite — it clarifies and reinforces. Option D is wrong because repeating a line adds length rather than shortening the poem." },
  { id: '5a84d0c0-0d8f-4aec-9b42-26d7d9252909', hint_en: "Think about which character the plot centers on — whose goals and struggles drive the events from beginning to end.", hint_he: "חשבו על הדמות שסביבה מתרחשת העלילה — מי שהמטרות והקשיים שלו מניעים את הסיפור מההתחלה ועד הסוף.", explanation_en: "The word 'protagonist' comes from the Greek 'protos' (first) + 'agonistes' (actor/competitor) — literally the 'first actor,' meaning the character whose actions and choices drive the plot forward. That rules out the villain (who opposes the protagonist, often called the antagonist), the author (who writes the story but isn't part of it), and a supporting character (who has a smaller role). So 'protagonist' = the main character of the story." },
  { id: 'cb88f75b-e1e0-4aac-844e-a475ad682559', hint_en: "Think about the word's root: 'dia-' + 'logue' relates to speech between people — look for the option about talking, not about titles, events, or pictures.", hint_he: null, explanation_en: "The word dialogue comes from Greek roots meaning 'speech between' people. In a story, this refers to the actual words characters say to each other, usually shown in quotation marks — like when one character asks a question and another answers. That matches option A. The title (B), a list of events like a plot summary (C), and the cover picture (D) don't involve characters speaking, so they aren't dialogue." },
  { id: 'd0690a90-dd1d-4d4e-89be-e5202864b4ab', hint_en: "Think about the gap between what readers/viewers see and what the character on stage or in the story actually knows at that moment.", hint_he: "חשבו על הפער בין מה שהקוראים/הצופים יודעים לבין מה שהדמות עצמה יודעת באותו רגע בסיפור.", explanation_en: "Dramatic irony is defined specifically by a knowledge gap between audience and character — for example, in a story the reader may know a character is walking into a trap while the character believes everything is safe. That mismatch (audience informed, character not) is what makes B correct. A is just humor, C is conflict between characters, and D is about plot twists, none of which require the audience to know something the character doesn't — so they don't fit the definition." },
  { id: 'd09d17a5-1b4f-4644-8ca1-ccbcce8c7db2', hint_en: "Think about how poems are visually organized on the page — look for the blank spaces separating chunks of text.", hint_he: "חשבו איך שיר מסודר על העמוד - שימו לב לרווחים המפרידים בין קבוצות של שורות.", explanation_en: "A stanza (בית) is formed when several lines of a poem are grouped together, separated from other groups by a blank line — the same way sentences are grouped into paragraphs in prose. So option B is correct: it's not one word (A), not the title (C), and not just the last line (D), but a whole cluster of lines that work together as one unit of the poem." },
  { id: 'daca5d1f-8796-4a66-9a17-2f02dfea6a44', hint_en: "Think about the standard story structure — what does a reader need to know before any problem or event can happen?", hint_he: null, explanation_en: "A story follows a structure: exposition (characters/setting) → rising action/problem → climax → resolution/lesson. The lesson and solution come only after a problem exists, and a signature isn't part of the narrative at all — so the story must open with A, introducing who the characters are and where the story takes place, since that's needed before any conflict can be understood." },
  { id: 'f2d51a85-163b-4d08-9003-c616836b4c9a', hint_en: "Look at the words 'No one expected' — what does that phrase usually signal is coming next in a story?", hint_he: null, explanation_en: "The passage sets up an expectation ('No one expected the quiet girl to win') and then overturns it when she wins and silences the room. This gap between what the reader/characters anticipated and what actually happens is the definition of surprise — not humor (nothing comic occurs), not repetition (no word or idea is repeated), and not instruction (no lesson is being taught)." },]

if (new Set(UPDATES.map(u => u.id)).size !== UPDATES.length) {
  throw new Error('duplicate id in UPDATES — aborting before touching the DB')
}

let updated = 0, skipped = 0, failed = 0

for (const u of UPDATES) {
  const { data: current, error: fetchErr } = await supabase
    .from('questions')
    .select('tags')
    .eq('id', u.id)
    .single()

  if (fetchErr || !current) {
    console.log(`  ${u.id}: FAILED to fetch — ${fetchErr?.message || 'not found'}`)
    failed++
    continue
  }

  const existingTags = Array.isArray(current.tags) ? current.tags : []
  if (existingTags.includes(TAG)) {
    console.log(`  ${u.id}: skipped (already tagged)`)
    skipped++
    continue
  }

  const { error: updateErr } = await supabase
    .from('questions')
    .update({
      hint_en: u.hint_en,
      hint_he: u.hint_he,
      explanation_en: u.explanation_en,
      tags: [...existingTags, TAG],
    })
    .eq('id', u.id)

  if (updateErr) {
    console.log(`  ${u.id}: FAILED to update — ${updateErr.message}`)
    failed++
    continue
  }

  updated++
}

console.log(`\nDone. ${updated} updated, ${skipped} already tagged (skipped), ${failed} failed.`)
